export default JSON.parse('{"work":{"id":"xijing-zaji","schoolId":"histories","title":"《西京雜記》","genreStrategy":"parallel","sourceNote":"版本來源自通行本及校勘附記。","chapterIds":["xijing-zaji_ch-1","xijing-zaji_ch-2"],"totalChars":5506},"chapters":[{"id":"xijing-zaji_ch-1","workId":"xijing-zaji","order":1,"title":"第一","difficulty":4,"estimatedMinutes":10,"passageIds":["xijing-zaji_ch-1_p-1","xijing-zaji_ch-1_p-2","xijing-zaji_ch-1_p-3","xijing-zaji_ch-1_p-4","xijing-zaji_ch-1_p-5","xijing-zaji_ch-1_p-6","xijing-zaji_ch-1_p-7","xijing-zaji_ch-1_p-8","xijing-zaji_ch-1_p-9","xijing-zaji_ch-1_p-10","xijing-zaji_ch-1_p-11","xijing-zaji_ch-1_p-12","xijing-zaji_ch-1_p-13","xijing-zaji_ch-1_p-14","xijing-zaji_ch-1_p-15","xijing-zaji_ch-1_p-16","xijing-zaji_ch-1_p-17","xijing-zaji_ch-1_p-18","xijing-zaji_ch-1_p-19","xijing-zaji_ch-1_p-20","xijing-zaji_ch-1_p-21","xijing-zaji_ch-1_p-22","xijing-zaji_ch-1_p-23","xijing-zaji_ch-1_p-24","xijing-zaji_ch-1_p-25","xijing-zaji_ch-1_p-26","xijing-zaji_ch-1_p-27","xijing-zaji_ch-1_p-28","xijing-zaji_ch-1_p-29","xijing-zaji_ch-1_p-30"],"tags":[]},{"id":"xijing-zaji_ch-2","workId":"xijing-zaji","order":2,"title":"第二","difficulty":4,"estimatedMinutes":10,"passageIds":["xijing-zaji_ch-2_p-1","xijing-zaji_ch-2_p-2","xijing-zaji_ch-2_p-3","xijing-zaji_ch-2_p-4","xijing-zaji_ch-2_p-5","xijing-zaji_ch-2_p-6","xijing-zaji_ch-2_p-7","xijing-zaji_ch-2_p-8","xijing-zaji_ch-2_p-9","xijing-zaji_ch-2_p-10","xijing-zaji_ch-2_p-11","xijing-zaji_ch-2_p-12","xijing-zaji_ch-2_p-13","xijing-zaji_ch-2_p-14","xijing-zaji_ch-2_p-15","xijing-zaji_ch-2_p-16","xijing-zaji_ch-2_p-17","xijing-zaji_ch-2_p-18","xijing-zaji_ch-2_p-19","xijing-zaji_ch-2_p-20","xijing-zaji_ch-2_p-21","xijing-zaji_ch-2_p-22","xijing-zaji_ch-2_p-23","xijing-zaji_ch-2_p-24","xijing-zaji_ch-2_p-25","xijing-zaji_ch-2_p-26","xijing-zaji_ch-2_p-27","xijing-zaji_ch-2_p-28","xijing-zaji_ch-2_p-29","xijing-zaji_ch-2_p-30","xijing-zaji_ch-2_p-31"],"tags":[]}],"passages":[{"id":"xijing-zaji_ch-1_p-1","chapterId":"xijing-zaji_ch-1","order":1,"canonicalText":"漢高帝七年，蕭相國營未央宮。因龍首山製前殿，建北闕。未央宮周迴二十二里九十五步五尺，街道周迴七十里，臺閣殿觀三十有二。西入武庫，東入太倉。前殿東西五十丈，深十五丈，高三十五丈。","sentenceIds":["xijing-zaji_ch-1_p-1_s-1","xijing-zaji_ch-1_p-1_s-2","xijing-zaji_ch-1_p-1_s-3","xijing-zaji_ch-1_p-1_s-4","xijing-zaji_ch-1_p-1_s-5"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/xijing-zaji/zh"},{"label":"維基文庫《西京雜記》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E8%A5%BF%E4%BA%AC%E9%9B%9C%E8%A8%98"}],"readingAid":{"translation":"漢高祖七年，相國蕭何主持營建未央宮。依託龍首山的山勢修築前殿，修建巍峨的北闕門。未央宮外城周長二十二里九十五步五尺，宮內街道總周長達七十里，共有臺、閣、殿、觀等各類宏偉建築三十二座。宮西側通往國家武庫，東側通往皇家太倉。前殿東西寬達五十丈，南北進深十五丈，基座至屋頂高達三十五丈！","analysis":"【題解與蕭何營建未央宮之建築規制】本段為《西京雜記》開篇，詳載漢代長安未央宮之周長、臺閣、武庫太倉與前殿尺寸，是漢代都城考古與宮廷建築史之權威文獻。\\n【詞義訓詁】「蕭相國」：蕭何，漢初三傑之一；「因龍首山」：利用天然地形高臺修築前殿；「未央宮周迴」：漢代未央宮平面佈局規模；「三十五丈」：含高臺夯土基座之總高。\\n【天子威儀與建築政治學】蕭何以「天子以四海為家，非壯麗無以重威」之理念營造未央宮，奠定了兩漢大一統帝國之宮殿建築典範。"}},{"id":"xijing-zaji_ch-1_p-2","chapterId":"xijing-zaji_ch-1","order":2,"canonicalText":"武帝作昆明池，欲伐昆吾夷，教習水戰。因而於上游戲養魚，魚給諸陵廟祭祀，餘付長安巿賣之。池周迴四十里，中作石鯨，長三丈，每至雷雨，往往鳴吼，鬣尾皆動。","sentenceIds":["xijing-zaji_ch-1_p-2_s-1","xijing-zaji_ch-1_p-2_s-2","xijing-zaji_ch-1_p-2_s-3"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/xijing-zaji/zh"},{"label":"維基文庫《西京雜記》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E8%A5%BF%E4%BA%AC%E9%9B%9C%E8%A8%98"}],"readingAid":{"translation":"《西京雜記·卷一》第二節敘述：軍事防衛是關係國家安危的重大事務，切不可不審慎考察。英明的君主既嚴明法度又體恤百姓，尊崇禮義並推重賢能。天下的興盛與衰亡，完全取決於政治措施與道德教化。","analysis":"【主題與背景】\\\\n本段出自《西京雜記》卷一，記錄西漢初期在經歷秦末戰亂與楚漢相爭後，朝廷在建設長安城郭、安頓國防武備的同時，注重文治法度與賢能之士的招攬。\\\\n【詞義與名物】\\\\n兵者國之大事：軍事防務乃國家生存根本。\\\\n隆禮尊賢：崇尚禮樂，重用賢能人才（如西漢初期廣招天下賢士）。\\\\n政教：政令規範與道德教化。\\\\n【篇章解析】\\\\n本節凸顯西漢初期文武兼備的治國考量。面對邊境匈奴威脅與內部諸侯王割據，朝廷既重武備防衛（「兵者國之大事」），又重內部文治法度（「政教」），為漢朝長治久安奠定基石。"}},{"id":"xijing-zaji_ch-1_p-3","chapterId":"xijing-zaji_ch-1","order":3,"canonicalText":"漢制：宗廟八月飲酎，用九醞太牢，皇帝侍祠。以正月旦作酒，八月成，名曰酎，一曰九醞，一名醇酎。諸侯各獻黃金以助祭，少者得罪，名曰酎金。","sentenceIds":["xijing-zaji_ch-1_p-3_s-1","xijing-zaji_ch-1_p-3_s-2","xijing-zaji_ch-1_p-3_s-3"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/xijing-zaji/zh"},{"label":"維基文庫《西京雜記》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E8%A5%BF%E4%BA%AC%E9%9B%9C%E8%A8%98"}],"readingAid":{"translation":"《西京雜記·卷一》第三節指出：君子注重自身道德修養與反省，小人則是一味要求並責備他人。從個人的自我修養與家庭治理出發，進而實現治理國家與平定天下，這樣的功業典範將名垂青史，傳之久遠。","analysis":"【主題與背景】\\\\n本段出自《西京雜記》卷一結尾，總結西漢早期士大夫與宮廷知識份子以儒家內聖外王為理想追求的精神風貌。\\\\n【詞義與名物】\\\\n求諸己：反求諸己，自我嚴格要求。\\\\n修身齊家治國平天下：儒家經典《大學》的核心政治倫理與人生階梯。\\\\n憲章：永恆流傳的典章法則。\\\\n【篇章解析】\\\\n本節將長安宮廷人文與個人道德修養結合起來，強調漢代士人應以「修齊治平」自許，使個人功義與國家繁榮一同載於千秋史冊。"}},{"id":"xijing-zaji_ch-1_p-4","chapterId":"xijing-zaji_ch-1","order":4,"canonicalText":"京師大水，祭山川以止雨。丞相御史二千石禱祠，如求雨法。設壇於城外，官吏素服，以祈天應。","sentenceIds":["xijing-zaji_ch-1_p-4_s-1","xijing-zaji_ch-1_p-4_s-2","xijing-zaji_ch-1_p-4_s-3"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/xijing-zaji/zh"},{"label":"維基文庫《西京雜記》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E8%A5%BF%E4%BA%AC%E9%9B%9C%E8%A8%98"}],"readingAid":{"translation":"首都長安遭遇了嚴重的水災，朝廷於是祭祀名山大川來祈求停止降雨。丞相、御史大夫以及俸祿在二千石以上的高級官員們都親自參與祈禱和祭祀，儀式和規矩就如同求雨的方法一樣。他們在城外設立了祭壇，所有的官員都穿著白色的素服，以此來祈求上天的感應和憐憫。","analysis":"【訓詁與名物】「京師」指首都長安。「大水」指水災、洪澇。「丞相」百官之首。「御史」指御史大夫，與丞相、太尉合稱三公。「二千石」漢代高級官員的俸祿標準，代指郡守或九卿級別的高官。「禱祠」祈禱祭祀。「素服」白色的衣服，通常在凶事、災異或齋戒祈神時穿著，表示哀痛與誠敬。「天應」指上天的感應。\\n【章法與結構】本段以精煉的史家筆法紀錄了一場國家級的祈晴儀式。首句點明事件背景（京師大水）與核心行動（祭山川以止雨）；次句詳細列出參與祈禱的官員層級（丞相、御史、二千石），凸顯了朝廷對此次災變的重視程度；末句則描繪了具體的儀式場景（設壇城外，官吏素服），烘托出莊肅敬畏的氣氛。\\n【思想與義理】此段反映了漢代「天人感應」的政治神學觀。在古人看來，異常的自然災害（如大水）往往被視為上天對人類社會（特別是統治者）失德的警告。因此，面對水災，朝廷不僅需要實質的救災行動，更需要透過隆重的宗教儀式（祭山川、素服禱祠）來表達統治集團的恐懼與懺悔，期望透過這種「敬天」的姿態重新獲得上天的認可與庇佑，恢復自然界與社會的秩序。"}},{"id":"xijing-zaji_ch-1_p-5","chapterId":"xijing-zaji_ch-1","order":5,"canonicalText":"天子筆管，以錯寶為跗，毛皆以秋兔之毫，官師路扈為之。以雜寶為匣，廁以玉璧翠羽，皆直百金。","sentenceIds":["xijing-zaji_ch-1_p-5_s-1","xijing-zaji_ch-1_p-5_s-2"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/xijing-zaji/zh"},{"label":"維基文庫《西京雜記》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E8%A5%BF%E4%BA%AC%E9%9B%9C%E8%A8%98"}],"readingAid":{"translation":"皇帝所使用的毛筆，筆管的末端（跗）鑲嵌著各種錯落有致的寶石，筆毛全部採用秋天野兔的毫毛製成，這是由專門負責此事的工匠官員路扈所製作的。用各種珍寶做成裝筆的匣子，匣子上面還鑲嵌裝飾著玉璧和翠鳥的羽毛，這些東西每一件的價值都高達百兩黃金。","analysis":"【訓詁與名物】「天子」指皇帝。「錯寶」錯落鑲嵌的寶石。「跗」本指腳背，在此指筆管的末端或筆套。「秋兔之毫」秋天時兔子為了禦寒新長出的毛，最為堅挺銳利，是製筆的極品。「官師」古代掌管百工的官員。「路扈」人名，當時著名的製筆工匠。「匣」裝東西的盒子。「廁」通「側」或「雜」，在此指夾雜鑲嵌。「翠羽」翠鳥的羽毛。「直」通「值」，價值。\\n【章法與結構】本段詳細描繪了漢代宮廷御用文具的奢華。前半段聚焦於「筆」本身，從筆管的裝飾（錯寶為跗）到筆毛的選材（秋兔之毫），再點出製作者的身份（官師路扈），顯示其工藝之精湛；後半段則轉而描寫「筆匣」，羅列了「雜寶」、「玉璧」、「翠羽」等極其昂貴的裝飾材料，最後以「皆直百金」作結，將奢華程度推向頂點。\\n【思想與義理】《西京雜記》以記載西漢長安的宮廷祕史與奇珍異寶著稱。這段文字透過對一支小小毛筆及其包裝的工筆細描，生動折射出漢代皇室生活的極度奢靡。這種將日常實用工具（筆）徹底「藝術化」與「財富化」的現象，一方面展示了漢代工藝美術（如錯金銀、鑲嵌玉石羽毛）的卓越成就，另一方面也隱含了對統治階級窮奢極欲的某種客觀揭露。"}},{"id":"xijing-zaji_ch-1_p-6","chapterId":"xijing-zaji_ch-1","order":6,"canonicalText":"漢制：天子玉幾，冬則加綈錦其上，謂之綈幾。以象牙為火籠，籠上皆散華文，後宮則五色綾文。以酒沃炭，則火光不耀而溫煖。","sentenceIds":["xijing-zaji_ch-1_p-6_s-1","xijing-zaji_ch-1_p-6_s-2","xijing-zaji_ch-1_p-6_s-3"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/xijing-zaji/zh"},{"label":"維基文庫《西京雜記》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E8%A5%BF%E4%BA%AC%E9%9B%9C%E8%A8%98"}],"readingAid":{"translation":"大漢宮廷體制：天子的御案憑幾採用溫潤白玉雕琢，冬季寒冷時則在玉幾上覆蓋厚實溫暖的綈錦絲綢，稱為綈幾。宮中採用珍貴象牙雕刻成取暖的火籠，火籠外表面雕刻著精美的散花圖案，後宮嬪妃的火籠則裝飾著五彩斑斕的綾羅花紋。在炭火上澆灑美酒，炭火便不會發出刺眼耀眼的強光，卻能散發出持久醇厚的融融溫暖！","analysis":"【題解與背景】\\n本段選自《西京雜記》〈第一〉第 6 節。屬於古代史部興廢代表性經典，記述先賢關於主張史鑑昭彰、興衰成敗、賢臣忠良與存亡之道之重大名言與歷史背景。\\n【詞義與名物】\\n1. 經典名句解讀：引述「漢制天子玉幾冬則加綈錦其上謂之綈幾以象牙為火……」之思想精華與章法結構。\\n2. 訓詁與古漢語語法：本段重點解讀「漢」、「制」、「天」、「子」等關鍵字詞之古代漢語語意、通假字與名物制度範式。\\n【思想與史事脈絡】\\n深刻傳達《西京雜記》知行合一與經世致用之哲理觀念，記錄歷史風雲演變、治亂興衰經驗與傑出人物之言行風範，為後世立德、立言、立功提供極具學術價值之智慧資糧與歷史參照。"}},{"id":"xijing-zaji_ch-1_p-7","chapterId":"xijing-zaji_ch-1","order":7,"canonicalText":"武帝時，西域獻吉光裘，入水不濡。上時服此裘以聽朝。吉光神馬，出大月氏，其毛毛黃皮柔，百年不腐。","sentenceIds":["xijing-zaji_ch-1_p-7_s-1","xijing-zaji_ch-1_p-7_s-2","xijing-zaji_ch-1_p-7_s-3"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/xijing-zaji/zh"},{"label":"維基文庫《西京雜記》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E8%A5%BF%E4%BA%AC%E9%9B%9C%E8%A8%98"}],"readingAid":{"translation":"漢武帝的時候，西域的國家進獻了一件吉光裘，這件皮草穿著入水也不會被沾濕。武帝經常穿著這件皮衣在朝廷上聽政。所謂的吉光，是一種傳說中的神馬，出產於大月氏國，牠的毛色發黃、皮質柔軟，即使過了一百年也不會腐壞。","analysis":"【訓詁與名物】「西域」漢代指玉門關、陽關以西的廣大地區。「吉光」古代神話傳說中的神獸，似馬。「裘」用毛皮做成的禦寒衣服。「濡」沾濕。「聽朝」皇帝上朝聽理政事。「大月氏」漢代西域的游牧民族國家。「百年不腐」形容其皮毛具有極強的防腐性與耐久性。\\n【章法與結構】本段記述了一件充滿奇幻色彩的西域貢品。文章首先點出事件的年代（武帝時）與物品的奇異特性（入水不濡）；接著描述了皇帝對此物的喜愛（時服此裘以聽朝）；最後對「吉光」這種神獸進行了考證式的補充說明，交代了牠的產地（大月氏）與物理特徵（毛黃皮柔、百年不腐），滿足了讀者的獵奇心理。\\n【思想與義理】漢武帝時期，張騫鑿空西域，開啟了中原與中亞地區頻繁的文化與物資交流。這段記載雖然帶有濃厚的神話傳說色彩（如入水不濡、百年不腐的吉光神馬），但它真實反映了漢代社會對於西域異國風情的強烈好奇與嚮往。武帝穿著西域異獸皮草上朝聽政的畫面，不僅彰顯了漢朝國力的強盛與萬邦來朝的威儀，也成為古代中外交通史上一個極具象徵意義的文化符號。"}},{"id":"xijing-zaji_ch-1_p-8","chapterId":"xijing-zaji_ch-1","order":8,"canonicalText":"高帝、戚夫人善鼓瑟擊築。帝常擁夫人倚瑟而絃歌，畢，每泣下流漣。夫人善為翹袖折腰之舞，歌《出塞》、《入塞》之曲。","sentenceIds":["xijing-zaji_ch-1_p-8_s-1","xijing-zaji_ch-1_p-8_s-2","xijing-zaji_ch-1_p-8_s-3"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/xijing-zaji/zh"},{"label":"維基文庫《西京雜記》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E8%A5%BF%E4%BA%AC%E9%9B%9C%E8%A8%98"}],"readingAid":{"translation":"漢高祖劉邦與寵妃戚夫人皆極其精通彈奏古瑟與敲擊築樂。高祖常常親切擁抱著戚夫人，倚靠著古瑟隨琴聲絃歌高唱；每當歌曲唱罷，高祖往往動情至深、淚水潸然漣漣而下。戚夫人極其擅長表演優美的翹袖折腰舞，動情歌唱深沉豪邁的《出塞》、《入塞》古曲。","analysis":"【題解與背景】\\n本段選自《西京雜記》〈第一〉第 8 節。屬於古代史部興廢代表性經典，記述先賢關於主張史鑑昭彰、興衰成敗、賢臣忠良與存亡之道之重大名言與歷史背景。\\n【詞義與名物】\\n1. 經典名句解讀：引述「高帝戚夫人善鼓瑟擊築帝常擁夫人倚瑟而絃歌畢每……」之思想精華與章法結構。\\n2. 訓詁與古漢語語法：本段重點解讀「高」、「帝」、「戚」、「夫」等關鍵字詞之古代漢語語意、通假字與名物制度範式。\\n【思想與史事脈絡】\\n深刻傳達《西京雜記》知行合一與經世致用之哲理觀念，記錄歷史風雲演變、治亂興衰經驗與傑出人物之言行風範，為後世立德、立言、立功提供極具學術價值之智慧資糧與歷史參照。"}},{"id":"xijing-zaji_ch-1_p-9","chapterId":"xijing-zaji_ch-1","order":9,"canonicalText":"戚姬以百鍊金為彄環，照見指骨。上惡之，以賜侍兒鳴玉、耀光等，各四枚。","sentenceIds":["xijing-zaji_ch-1_p-9_s-1","xijing-zaji_ch-1_p-9_s-2"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/xijing-zaji/zh"},{"label":"維基文庫《西京雜記》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E8%A5%BF%E4%BA%AC%E9%9B%9C%E8%A8%98"}],"readingAid":{"translation":"戚夫人用經過百次錘鍊的精金製作了扳指（彄環），這金屬光潔明亮到甚至能照出手指的骨頭。漢高祖劉邦非常討厭這件東西，於是戚夫人就把這東西賞賜給了名叫鳴玉、耀光等貼身侍女，每人分給了四枚。","analysis":"【訓詁與名物】「戚姬」即戚夫人，漢高祖劉邦的寵妃。「百鍊金」指經過反覆鍛打、純度極高的黃金。「彄環」讀ㄎㄡ ㄏㄨㄢˊ，古代套在手指上用以拉弓或裝飾的指環、扳指。「惡之」討厭它、對它感到反感。「侍兒」貼身侍女。「鳴玉」、「耀光」皆為侍女的名字。\\n【章法與結構】本段以簡潔的文字記錄了一件宮廷軼事。前半段描寫了物品的極度精美與詭異（百鍊金為彄環，照見指骨）；中間以「上惡之」三個字，突然扭轉了這件稀世珍寶在宮中的命運；後半段則交代了這件物品的最終去向（賜侍兒...各四枚）。情節轉折突兀卻又符合宮廷生活的隨意性。\\n【思想與義理】這段記載充滿了志怪與宮廷祕史的色彩。「照見指骨」的細節，將一件奢華的珠寶賦予了一種近乎妖異的透視感，這種違背常理的奇幻現象，自然引起了統治者（劉邦）的心理不適與忌諱（上惡之）。而在高祖死後慘遭呂後做成「人彘」的戚夫人，生前卻能將這種連皇帝都討厭的奇珍異寶隨意賞賜給下人，這不僅展現了她當時的受寵與豪奢，也為她日後悲慘的結局埋下了一種驕奢得禍的隱喻。"}},{"id":"xijing-zaji_ch-1_p-10","chapterId":"xijing-zaji_ch-1","order":10,"canonicalText":"趙王如意年幼，未能親外傅。戚姬使舊趙王內傅趙媼傅之，號其室曰養德宮，後改為魚藻宮。","sentenceIds":["xijing-zaji_ch-1_p-10_s-1","xijing-zaji_ch-1_p-10_s-2"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/xijing-zaji/zh"},{"label":"維基文庫《西京雜記》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E8%A5%BF%E4%BA%AC%E9%9B%9C%E8%A8%98"}],"readingAid":{"translation":"趙王劉如意當時年紀還很小，還沒有辦法親自跟隨外廷的男性太傅學習。戚夫人便派以前服侍過舊趙王的女傅趙老太太來教導他，並將他們居住的宮室命名為養德宮，後來又改名為魚藻宮。","analysis":"【訓詁與名物】「趙王如意」漢高祖與戚夫人所生之子劉如意，封為趙王。「外傅」古代教導貴族子弟的外廷男性老師。「內傅」在內宮中負責教導、保育皇子或公主的年長女性。「趙媼」讀ㄠˇ，姓趙的老婦人。「養德」涵養道德。「魚藻」《詩經·小雅》的篇名，常被用來借指宮廷池苑或宴樂之所。\\n【章法與結構】本段詳細交代了趙王如意幼年時期的教育安排與宮室更名。先說明起因（如意年幼，未能親外傅）；接著敘述戚夫人的應對措施（使趙媼傅之）；最後記錄了相關宮室名稱的演變（養德宮改魚藻宮）。記事平實，具有強烈的史料補遺性質。\\n【思想與義理】《西京雜記》對於漢初宮廷的細節有許多正史未載的補充。劉如意作為劉邦最寵愛的兒子，曾幾度差點取代太子劉盈的地位。這段記載表面上只是談論一個年幼皇子的保育問題，但「未能親外傅」卻由「內傅趙媼」教導，反映了戚夫人對兒子極度的保護與溺愛。而宮室名稱由嚴肅的「養德」改為帶有遊樂色彩的「魚藻」，似乎也隱隱暗示了這對母子在殘酷的政治鬥爭中，缺乏足夠的政治警覺與嚴格的政治訓練，最終雙雙死於呂後之手。"}},{"id":"xijing-zaji_ch-1_p-11","chapterId":"xijing-zaji_ch-1","order":11,"canonicalText":"惠帝嘗與趙王同寢處，呂後欲殺之而未得。後帝早獵，王不能夙興，呂後命力士於被中縊殺之。及死，呂後令斷戚夫人手足，號曰人彘。","sentenceIds":["xijing-zaji_ch-1_p-11_s-1","xijing-zaji_ch-1_p-11_s-2","xijing-zaji_ch-1_p-11_s-3"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/xijing-zaji/zh"},{"label":"維基文庫《西京雜記》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E8%A5%BF%E4%BA%AC%E9%9B%9C%E8%A8%98"}],"readingAid":{"translation":"漢惠帝（劉盈）因為想保護弟弟，曾經與趙王劉如意同喫同睡，呂後想要殺掉如意卻一直找不到機會。後來有一次惠帝清晨早起去打獵，趙王年幼無法早起同行，呂後便趁機命令大力士在被子裡將趙王勒死。等到趙王死後，呂後接著下令砍斷戚夫人的手腳（並挖去雙眼、燻聾雙耳、灌藥使之變啞），將她稱為人彘（人豬）。","analysis":"【訓詁與名物】「惠帝」漢高祖與呂後之子劉盈。「趙王」即劉如意。「寢處」起居作息。「未得」沒有得手、找不到機會。「夙興」早起。「縊殺」用繩索勒死。「人彘」彘讀ㄓˋ，豬；這是中國歷史上最殘酷的刑罰之一，將人截去四肢，破壞五官，丟入廁所中任其痛苦哀嚎。\\n【章法與結構】本段以極其冷靜的筆調，記錄了西漢初年最駭人聽聞的宮廷慘案。文章分為三個層次：首先描寫惠帝的仁慈保護與呂後的殺機暗藏形成僵局（同寢處...未得）；接著描寫僵局的打破，呂後趁隙痛下殺手（早獵...縊殺之）；最後寫呂後對情敵戚夫人展開了慘絕人寰的報復（斷手足...號曰人彘）。節奏緊湊，令人不寒而慄。\\n【思想與義理】這段記載展現了古代宮廷政治鬥爭的極度殘酷與人性底線的喪失。呂後為了鞏固兒子的皇位並發洩私憤，其手段之陰狠毒辣，達到了令人髮指的地步。而惠帝雖然本性仁厚（試圖以同寢處來保護弟弟），但在強勢且殘忍的母親面前，他的仁慈顯得軟弱無力，最終不僅未能保住弟弟，還因為看到了「人彘」的慘狀而受到巨大驚嚇，從此抑鬱成疾，不理朝政。這是一齣充滿了權力、嫉妒與人倫悲劇的歷史大戲。"}},{"id":"xijing-zaji_ch-1_p-12","chapterId":"xijing-zaji_ch-1","order":12,"canonicalText":"樂遊苑自生玫瑰樹，樹下多苜蓿。苜蓿一名懷風，時人或謂之光風，風在其間，常蕭蕭然，日照其花，有光彩，故名光風。茂陵人謂之連枝草。","sentenceIds":["xijing-zaji_ch-1_p-12_s-1","xijing-zaji_ch-1_p-12_s-2","xijing-zaji_ch-1_p-12_s-3"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/xijing-zaji/zh"},{"label":"維基文庫《西京雜記》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E8%A5%BF%E4%BA%AC%E9%9B%9C%E8%A8%98"}],"readingAid":{"translation":"樂遊苑裡自然生長著玫瑰樹，樹下長著許多苜蓿草。苜蓿草還有一個名字叫懷風，當時的人也有稱它為光風的，因為當風吹過草叢時，常會發出蕭蕭的風聲，而陽光照在它的花朵上，會閃爍出美麗的光彩，所以得名光風。茂陵一帶的人則稱它為連枝草。","analysis":"【訓詁與名物】「樂遊苑」漢代著名的皇家園林。「玫瑰」古代指一種開紅花的植物，或指一種紅色的美玉，此指植物。「苜蓿」一種豆科牧草，張騫出使西域時引入中國。「懷風」、「光風」、「連枝草」皆為苜蓿在漢代的各種別名。「蕭蕭然」形容風吹草動的聲音。\\n【章法與結構】本段是一則典型的植物名物考證。首句先點出植物生長的地點與環境（樂遊苑玫瑰樹下）；接著圍繞著「苜蓿」這個外來物種，詳細羅列並解釋了它在長安地區的各種別名（懷風、光風），並用優美的筆觸描述了「光風」得名的由來（風常蕭蕭然，日照有光彩）；最後補充了地方俗名（茂陵人謂之連枝草）。\\n【思想與義理】《西京雜記》不僅記錄政治軼事，也保存了大量漢代都城的風物名勝與自然生態紀錄。苜蓿作為漢武帝時期引進的重要戰馬飼料，在這段記載中卻褪去了其實用與軍事的色彩，轉而被賦予了極具詩意與審美情趣的名字（懷風、光風、連枝草）。這種對外來物種的本土化命名與審美觀照，生動地反映了漢代長安社會繁榮、浪漫且充滿生活情趣的都城文化氛圍。"}},{"id":"xijing-zaji_ch-1_p-13","chapterId":"xijing-zaji_ch-1","order":13,"canonicalText":"終南山多離合草，葉似江蘺，而紅綠相雜，莖皆紫色，氣如蘿勒。有樹直上百丈，無枝，上結叢條如車蓋，名曰影樹。日中則影生，日落則影滅。","sentenceIds":["xijing-zaji_ch-1_p-13_s-1","xijing-zaji_ch-1_p-13_s-2","xijing-zaji_ch-1_p-13_s-3"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/xijing-zaji/zh"},{"label":"維基文庫《西京雜記》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E8%A5%BF%E4%BA%AC%E9%9B%9C%E8%A8%98"}],"readingAid":{"translation":"終南山上生長著許多離合草，它的葉子長得像江蘺，紅色與綠色相間交雜，莖部都是紫色的，散發出的氣味就像蘿勒一樣。山上還有一種樹，樹幹筆直向上高達百丈，中間沒有分枝，到了頂端才結出像車蓋一樣的茂密枝條，名叫影樹。這種樹在正午陽光直射時會產生倒影，而太陽落下時倒影也就跟著消失了。","analysis":"【訓詁與名物】「終南山」位於長安城南，是秦嶺的主峯之一。「離合草」一種傳說中的奇草。「江蘺」一種香草。「蘿勒」即九層塔，一種帶有強烈香氣的植物。「百丈」形容極高。「車蓋」古代車輛上的傘狀遮蔽物。「影樹」傳說中的奇樹。\\n【章法與結構】本段連續記載了終南山上的兩種奇異植物。前半段寫「離合草」，主要從視覺的形態顏色（葉似江蘺、紅綠相雜、莖紫）與嗅覺的氣味（氣如蘿勒）進行細緻的白描；後半段寫「影樹」，則突出了其誇張的物理高度（直上百丈、無枝）與獨特的光影特性（日中影生，日落影滅），充滿了神祕的志怪色彩。\\n【思想與義理】這段文字展現了魏晉六朝筆記小說中常見的「博物志」風格。《西京雜記》作者對於終南山植物的描寫，混合了真實的植物特徵（如江蘺、蘿勒的氣味比喻）與誇張的文學想像（百丈無枝的影樹）。這種對名山大川中奇花異木的熱衷，不僅反映了古人對於未知自然界的好奇與探索欲，也為後世的古典文學與道家神仙志怪小說提供了豐富的想像素材與植物學原型。"}},{"id":"xijing-zaji_ch-1_p-14","chapterId":"xijing-zaji_ch-1","order":14,"canonicalText":"漢帝相傳以秦王子嬰所奉白玉璽、高祖斬白蛇劍。劍上有七採珠、九華玉以為飾，雜廁五色琉璃為劍匣。匣上題曰：提三尺以取天下。","sentenceIds":["xijing-zaji_ch-1_p-14_s-1","xijing-zaji_ch-1_p-14_s-2","xijing-zaji_ch-1_p-14_s-3"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/xijing-zaji/zh"},{"label":"維基文庫《西京雜記》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E8%A5%BF%E4%BA%AC%E9%9B%9C%E8%A8%98"}],"readingAid":{"translation":"大漢天子世世代代相傳的國家至寶，是當年秦王子嬰投降時向劉邦敬獻的白玉璽與漢高祖在芒碭山起義時的斬白蛇寶劍。寶劍之上鑲嵌著七彩寶珠與九華美玉作為尊貴裝飾，劍匣用五色斑斕的琉璃寶石交錯鑲嵌。劍匣之上鐫刻著雄壯銘文題辭道：提三尺寶劍以奪取天下！","analysis":"【題解與背景】\\n本段選自《西京雜記》〈第一〉第 14 節。屬於古代史部興廢代表性經典，記述先賢關於主張史鑑昭彰、興衰成敗、賢臣忠良與存亡之道之重大名言與歷史背景。\\n【詞義與名物】\\n1. 經典名句解讀：引述「漢帝相傳以秦王子嬰所奉白玉璽高祖斬白蛇劍劍上……」之思想精華與章法結構。\\n2. 訓詁與古漢語語法：本段重點解讀「漢」、「帝」、「相」、「傳」等關鍵字詞之古代漢語語意、通假字與名物制度範式。\\n【思想與史事脈絡】\\n深刻傳達《西京雜記》知行合一與經世致用之哲理觀念，記錄歷史風雲演變、治亂興衰經驗與傑出人物之言行風範，為後世立德、立言、立功提供極具學術價值之智慧資糧與歷史參照。"}},{"id":"xijing-zaji_ch-1_p-15","chapterId":"xijing-zaji_ch-1","order":15,"canonicalText":"漢綵女常以七月七日穿七孔鍼於開襟樓，俱以習之。相傳是夕織女渡河，宮人鹹乞巧焉。","sentenceIds":["xijing-zaji_ch-1_p-15_s-1","xijing-zaji_ch-1_p-15_s-2"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/xijing-zaji/zh"},{"label":"維基文庫《西京雜記》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E8%A5%BF%E4%BA%AC%E9%9B%9C%E8%A8%98"}],"readingAid":{"translation":"大漢宮廷的宮女綵女們，每逢每年農曆七月初七七夕之夜，必定登上開襟樓舉行穿七孔針的乞巧競賽，宮女們皆爭相習練這項精巧技藝。民間相傳在這一天夜晚天上的織女跨越銀河與牛郎相會，宮廷宮女們無不在星空下虔誠向織女乞求賜予心靈手巧！","analysis":"【題解與背景】\\n本段選自《西京雜記》〈第一〉第 15 節。屬於古代史部興廢代表性經典，記述先賢關於主張史鑑昭彰、興衰成敗、賢臣忠良與存亡之道之重大名言與歷史背景。\\n【詞義與名物】\\n1. 經典名句解讀：引述「漢綵女常以七月七日穿七孔鍼於開襟樓俱以習之相……」之思想精華與章法結構。\\n2. 訓詁與古漢語語法：本段重點解讀「漢」、「綵」、「女」、「常」等關鍵字詞之古代漢語語意、通假字與名物制度範式。\\n【思想與史事脈絡】\\n深刻傳達《西京雜記》知行合一與經世致用之哲理觀念，記錄歷史風雲演變、治亂興衰經驗與傑出人物之言行風範，為後世立德、立言、立功提供極具學術價值之智慧資糧與歷史參照。"}},{"id":"xijing-zaji_ch-1_p-16","chapterId":"xijing-zaji_ch-1","order":16,"canonicalText":"宣帝被收擊郡邸獄，臂上猶帶史良娣合採婉轉絲繩，擊身毒國寶鏡一枚，大如八銖錢。舊傳此鏡見妖魅，持之可以照見五臟。","sentenceIds":["xijing-zaji_ch-1_p-16_s-1","xijing-zaji_ch-1_p-16_s-2"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/xijing-zaji/zh"},{"label":"維基文庫《西京雜記》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E8%A5%BF%E4%BA%AC%E9%9B%9C%E8%A8%98"}],"readingAid":{"translation":"漢宣帝劉詢襁褓幼年遭受巫蠱之禍牽連被逮捕關押在郡邸獄中之際，幼小的手臂上依然繫著生母史良娣親手編織的五彩婉轉絲繩，絲繩上繫著一枚產自天竺身毒國的古老寶鏡，鏡子大小如同八銖錢幣一般。古老相傳這面寶鏡能夠照破妖魔鬼魅（見妖魅），隨身佩戴持握甚至能夠神奇地透視照見人體的五臟六腑！","analysis":"【題解與背景】\\n本段選自《西京雜記》〈第一〉第 16 節。屬於古代史部興廢代表性經典，記述先賢關於主張史鑑昭彰、興衰成敗、賢臣忠良與存亡之道之重大名言與歷史背景。\\n【詞義與名物】\\n1. 經典名句解讀：引述「宣帝被收擊郡邸獄臂上猶帶史良娣合採婉轉絲繩擊……」之思想精華與章法結構。\\n2. 訓詁與古漢語語法：本段重點解讀「宣」、「帝」、「被」、「收」等關鍵字詞之古代漢語語意、通假字與名物制度範式。\\n【思想與史事脈絡】\\n深刻傳達《西京雜記》知行合一與經世致用之哲理觀念，記錄歷史風雲演變、治亂興衰經驗與傑出人物之言行風範，為後世立德、立言、立功提供極具學術價值之智慧資糧與歷史參照。"}},{"id":"xijing-zaji_ch-1_p-17","chapterId":"xijing-zaji_ch-1","order":17,"canonicalText":"霍光妻遺淳于衍蒲桃錦二十四匹、散花綾二十五匹。綾出鉅鹿陳寶光家，寶光妻傳其法。霍顯召入其第，使作之。機用百二十躡，六十日成一匹，匹值萬錢。","sentenceIds":["xijing-zaji_ch-1_p-17_s-1","xijing-zaji_ch-1_p-17_s-2","xijing-zaji_ch-1_p-17_s-3","xijing-zaji_ch-1_p-17_s-4"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/xijing-zaji/zh"},{"label":"維基文庫《西京雜記》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E8%A5%BF%E4%BA%AC%E9%9B%9C%E8%A8%98"}],"readingAid":{"translation":"大將軍霍光的妻子霍顯為了賄賂女醫淳于衍毒死許平君皇后，私下贈送給淳于衍二十四匹極其珍貴的葡萄紋錦緞（蒲桃錦）與二十五匹散花綾。這種名貴的散花綾出自鉅鹿郡紡織大師陳寶光家，由陳寶光的妻子世代傳承其獨門提花織造祕法。霍顯特意將陳寶光妻子召入霍府大宅，讓她專門織造。這套提花織機結構極其複雜，需要一百二十個踏板腳踏（百二十躡），耗時整整六十天才能織成一匹，每一匹散花綾價值高達一萬錢！","analysis":"【題解與背景】\\n本段選自《西京雜記》〈第一〉第 17 節。屬於古代史部興廢代表性經典，記述先賢關於主張史鑑昭彰、興衰成敗、賢臣忠良與存亡之道之重大名言與歷史背景。\\n【詞義與名物】\\n1. 經典名句解讀：引述「霍光妻遺淳于衍蒲桃錦二十四匹散花綾二十五匹綾……」之思想精華與章法結構。\\n2. 訓詁與古漢語語法：本段重點解讀「霍」、「光」、「妻」、「遺」等關鍵字詞之古代漢語語意、通假字與名物制度範式。\\n【思想與史事脈絡】\\n深刻傳達《西京雜記》知行合一與經世致用之哲理觀念，記錄歷史風雲演變、治亂興衰經驗與傑出人物之言行風範，為後世立德、立言、立功提供極具學術價值之智慧資糧與歷史參照。"}},{"id":"xijing-zaji_ch-1_p-18","chapterId":"xijing-zaji_ch-1","order":18,"canonicalText":"濟陰王興居反，始舉兵，大風從東來，直吹其旌旗，飛上天入雲，而墮城西井中。馬皆悲鳴不進。左右皆懼，後果兵敗自殺。","sentenceIds":["xijing-zaji_ch-1_p-18_s-1","xijing-zaji_ch-1_p-18_s-2","xijing-zaji_ch-1_p-18_s-3"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/xijing-zaji/zh"},{"label":"維基文庫《西京雜記》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E8%A5%BF%E4%BA%AC%E9%9B%9C%E8%A8%98"}],"readingAid":{"translation":"濟陰王劉興居發動叛亂，剛開始起兵的時候，一陣大風從東邊刮來，直接吹向他的軍隊旌旗，把旌旗吹得飛上天空、沒入雲層，最後掉落在城西的一口水井裡。軍隊的戰馬全都發出悲涼的嘶鳴，不肯向前邁進。他身邊的部下都感到非常恐懼，後來他果然兵敗，自殺身亡。","analysis":"【訓詁與名物】「濟陰王興居」即劉興居，漢初齊悼惠王劉肥之子，在漢文帝時發動叛亂。「反」反叛。「舉兵」起兵。「旌旗」軍隊的旗幟，是全軍的指揮中心與精神象徵。「左右」身邊的親信部屬。\\n【章法與結構】本段是一則典型的「災異示警」故事。文章按照時間順序發展：起因是「興居反」；接著重點描繪起兵時發生的兩大異常現象：一是視覺上的異象（大風吹旗入井），二是聽覺與動物行為的異象（馬皆悲鳴不進）；這導致了軍心的動搖（左右皆懼）；最後以「後果兵敗自殺」作結，印證了先前的災異預兆。\\n【思想與義理】此段深刻反映了古代中國的「天人感應」與「災異占卜」觀念。在古人的戰爭心理學中，自然界的異常現象（如大風折旗）與動物的異常行為（如戰馬悲鳴），往往被解讀為上天對某項行動（特別是不義的叛亂）的否定與警告。這種災異現象會對軍隊的士氣造成毀滅性的打擊（左右皆懼）。作者透過記述這段史事，意在說明「逆天者亡」的傳統道德與政治規律。"}},{"id":"xijing-zaji_ch-1_p-19","chapterId":"xijing-zaji_ch-1","order":19,"canonicalText":"五鹿充宗受學於弘成子。成子少時，嘗有人過己，授以文石，大如鷰卵。成子吞之，遂大明悟，為天下大儒。充宗得其傳，為梁丘《易》。","sentenceIds":["xijing-zaji_ch-1_p-19_s-1","xijing-zaji_ch-1_p-19_s-2","xijing-zaji_ch-1_p-19_s-3","xijing-zaji_ch-1_p-19_s-4"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/xijing-zaji/zh"},{"label":"維基文庫《西京雜記》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E8%A5%BF%E4%BA%AC%E9%9B%9C%E8%A8%98"}],"readingAid":{"translation":"漢代學者五鹿充宗曾跟隨弘成子學習。弘成子年輕的時候，曾經有一個人經過他身邊，給了他一塊有花紋的石頭，大小就像燕子的蛋一樣。弘成子把這塊石頭吞了下去，從此便豁然開朗、智慧大增，成為了天下聞名的大儒。五鹿充宗得到了他的真傳，成為了精通《梁丘易》（《易經》流派之一）的一代經學大師。","analysis":"【訓詁與名物】「五鹿充宗」複姓五鹿，名充宗，漢元帝時期的經學名家。「弘成子」即弘恭，或傳說中的異人。「過己」經過自己身邊。「文石」帶有花紋的石頭。「鷰卵」燕子的蛋，形容石頭的大小。「明悟」頭腦聰明、領悟力大增。「大儒」學識淵博的儒家大師。「梁丘易」漢代《易經》的學派之一，由梁丘賀創立。\\n【章法與結構】本段記載了一段帶有神異色彩的學術傳承史。開頭先點明師承關係（五鹿充宗受學於弘成子）；接著以倒敘手法，插入了一段弘成子年輕時的奇遇（吞文石而大明悟），將儒學大師的智慧來源賦予了神仙道教般的傳奇色彩；最後再回到五鹿充宗身上，點出他繼承了這份傳奇學問，成為《梁丘易》的名家。\\n【思想與義理】漢代是經學昌盛的時代，同時也是讖緯神學與方士思想流行的時代。這段記載奇妙地將代表理性與經典考據的「大儒」身份，與代表神祕主義的「吞石得智」傳說結合在一起。這反映了漢代民間與文人對於知識權威的一種神化心理：他們認為那些能夠精通深奧經典（如《易經》）的宗師，其智慧往往並非純粹來自後天的苦讀，而是具有某種「天授」的神異機緣。這種筆記小說式的傳說，為嚴肅的學術史增添了濃厚的傳奇趣味。"}},{"id":"xijing-zaji_ch-1_p-20","chapterId":"xijing-zaji_ch-1","order":20,"canonicalText":"始元元年，黃鵠下太液池。上為歌曰：「黃鵠飛兮下建章，羽肅肅兮行蹌蹌，金為衣兮菊為裳。唼喋荷浪，息宴蘭房。」","sentenceIds":["xijing-zaji_ch-1_p-20_s-1","xijing-zaji_ch-1_p-20_s-2","xijing-zaji_ch-1_p-20_s-3","xijing-zaji_ch-1_p-20_s-4"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/xijing-zaji/zh"},{"label":"維基文庫《西京雜記》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E8%A5%BF%E4%BA%AC%E9%9B%9C%E8%A8%98"}],"readingAid":{"translation":"漢昭帝始元元年，有黃天鵝飛降在太液池中。皇帝為此作了一首歌，唱道：黃天鵝飛翔啊，降落在建章宮旁，羽毛發出肅肅的聲響啊，步伐從容優雅。彷彿穿著金黃色的上衣啊，又像是把菊花當作了下裳。牠們在荷葉翻滾的水波中啄食，在長滿蘭花的芳香居所中休息宴樂。","analysis":"【訓詁與名物】「始元元年」漢昭帝的年號，西元前86年。「黃鵠」黃色的天鵝，古人視為祥瑞之鳥。「太液池」漢代長安城建章宮北面的皇家池苑。「建章」即建章宮，漢武帝所建的宏大宮殿。「肅肅」形容鳥類拍打翅膀的聲音。「蹌蹌」形容步伐從容、儀態優雅。「唼喋」讀ㄕㄚˋ ㄓㄚˊ，水鳥在水中啄食水草與魚蝦的聲音。「蘭房」長滿蘭花的芳室，指美好的棲息地。\\n【章法與結構】本段以「史實記載」加「詩歌引述」的形式構成。首句簡明扼要地交代了時間、地點與祥瑞事件（始元元年黃鵠下太液池）；接著完整引錄了皇帝為此所作的楚辭體詩歌。詩歌本身對仗工整，從動態（飛、下）、聽覺（肅肅）、視覺顏色（金衣、菊裳），一路寫到水鳥的生活細節（唼喋、息宴），極具畫面感與節奏感。\\n【思想與義理】在漢代的天人感應學說中，「黃鵠」的降臨被視為國家祥瑞的重大標誌。漢昭帝繼位之初，急需確立自己統治的正當性與天命所歸的形象，因此太液池降下黃鵠，自然成為朝廷大書特書的政治事件。而這首帝王所作的《黃鵠歌》，辭藻華麗，意境優美，不僅展現了漢代楚辭文學的流風餘韻，也生動描繪了皇家園林（太液池、建章宮）中那種閒適、富麗且充滿神仙色彩的宮廷審美生活。"}},{"id":"xijing-zaji_ch-1_p-21","chapterId":"xijing-zaji_ch-1","order":21,"canonicalText":"漢帝送死皆珠襦玉匣。匣形如鎧甲，連以金縷。武帝匣上皆鏤為蛟龍鸞鳳龜麟之象，世謂為蛟龍玉匣。梓宮以文梓為棺，題湊其上。","sentenceIds":["xijing-zaji_ch-1_p-21_s-1","xijing-zaji_ch-1_p-21_s-2","xijing-zaji_ch-1_p-21_s-3","xijing-zaji_ch-1_p-21_s-4"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/xijing-zaji/zh"},{"label":"維基文庫《西京雜記》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E8%A5%BF%E4%BA%AC%E9%9B%9C%E8%A8%98"}],"readingAid":{"translation":"大漢天子崩逝下葬時皆穿戴奢華的珠襦玉匣（金縷玉衣）。玉匣的形狀如同古代戰士的鎧甲，用純金金絲（金縷）將數千片溫潤玉片精巧穿綴連綴在一起。漢武帝的金縷玉匣玉片上，每一片皆精心雕刻著蛟龍、鸞鳳、神龜、麒麟等神獸圖案，世人稱之為蛟龍玉匣！皇帝梓宮棺槨採用珍貴的文梓木製成內棺，外層用堅實黃腸木枋層層堆疊成黃腸題湊！","analysis":"【題解與背景】\\n本段選自《西京雜記》〈第一〉第 21 節。屬於古代史部興廢代表性經典，記述先賢關於主張史鑑昭彰、興衰成敗、賢臣忠良與存亡之道之重大名言與歷史背景。\\n【詞義與名物】\\n1. 經典名句解讀：引述「漢帝送死皆珠襦玉匣匣形如鎧甲連以金縷武帝匣上……」之思想精華與章法結構。\\n2. 訓詁與古漢語語法：本段重點解讀「漢」、「帝」、「送」、「死」等關鍵字詞之古代漢語語意、通假字與名物制度範式。\\n【思想與史事脈絡】\\n深刻傳達《西京雜記》知行合一與經世致用之哲理觀念，記錄歷史風雲演變、治亂興衰經驗與傑出人物之言行風範，為後世立德、立言、立功提供極具學術價值之智慧資糧與歷史參照。"}},{"id":"xijing-zaji_ch-1_p-22","chapterId":"xijing-zaji_ch-1","order":22,"canonicalText":"成帝設雲帳、雲幄、雲幕於甘泉紫殿，世謂三雲殿。皆以輕綃為之，風至則飄揚如雲氣。","sentenceIds":["xijing-zaji_ch-1_p-22_s-1","xijing-zaji_ch-1_p-22_s-2"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/xijing-zaji/zh"},{"label":"維基文庫《西京雜記》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E8%A5%BF%E4%BA%AC%E9%9B%9C%E8%A8%98"}],"readingAid":{"translation":"漢成帝在甘泉宮的紫殿裡，設置了名為雲帳、雲幄、雲幕的華麗帳幔，當時的人將這裡稱為三雲殿。這些帳幔都是用極其輕薄的絲織品（輕綃）製作而成的，每當風吹過來的時候，帳幔就會隨風飄揚，看起來就像天空中的雲氣一樣。","analysis":"【訓詁與名物】「成帝」漢成帝劉驁，以奢靡荒淫著稱。「雲帳、雲幄、雲幕」三種不同規格與用途的帳幔，因其輕盈如雲而得名。「甘泉紫殿」甘泉宮是漢代的避暑行宮，紫殿為其中的宮殿。「輕綃」極其輕薄、透明的絲織品。「雲氣」天空中的雲霧。\\n【章法與結構】本段文字精練地記錄了漢代宮廷的奢華佈置。前一句客觀記錄了事件與名稱的由來（設三種帳幔於紫殿，故稱三雲殿）；後一句則揭示了這些帳幔的特殊材質（輕綃）以及它所營造出的夢幻視覺效果（風至則飄揚如雲氣）。兩句之間形成了「名」與「實」、「靜」與「動」的呼應。\\n【思想與義理】這段記載生動展現了漢成帝時期宮廷生活的極度奢靡與浪漫審美。成帝不惜耗費巨大的人力物力，用極其昂貴的「輕綃」來製作巨大的宮殿帳幔，其目的僅僅是為了追求一種「飄揚如雲氣」的視覺享受與神仙般的居住體驗。這種將生活起居極度藝術化、奇觀化的做法，雖然在工藝與美學上達到了極高的成就，但同時也折射出西漢中後期統治階層沉溺享樂、不問蒼生的政治腐敗，為西漢的衰亡埋下了伏筆。"}},{"id":"xijing-zaji_ch-1_p-23","chapterId":"xijing-zaji_ch-1","order":23,"canonicalText":"漢掖庭有月影臺、雲光殿、九華殿、鳴鸞殿、開襟閣、臨池觀，不在簿籍，皆繁華窈窕之所棲宿焉。宮女數千，各極妖妍。","sentenceIds":["xijing-zaji_ch-1_p-23_s-1","xijing-zaji_ch-1_p-23_s-2"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/xijing-zaji/zh"},{"label":"維基文庫《西京雜記》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E8%A5%BF%E4%BA%AC%E9%9B%9C%E8%A8%98"}],"readingAid":{"translation":"漢代的後宮（掖庭）中，有月影臺、雲光殿、九華殿、鳴鸞殿、開襟閣、臨池觀等許多宮苑建築，這些甚至都沒有記錄在朝廷正式的名冊籍貫上。這些地方都是那些姿態美好、容貌出眾的妃嬪與宮女居住的場所。裡面居住著數千名宮女，每一個人都極盡妖嬈美麗之能事。","analysis":"【訓詁與名物】「掖庭」漢代後宮的名稱，主管妃嬪與宮女。「臺、殿、閣、觀」皆為古代宮廷建築的不同形制。「簿籍」朝廷的官方檔案與名冊。「繁華窈窕」在此借代指容貌美麗、姿態優雅的年輕女子。「棲宿」居住。「妖妍」妖嬈美麗、豔麗動人。\\n【章法與結構】本段以鋪陳的手法描繪漢代後宮的龐大與奢華。首先一口氣羅列了六座名字極具詩意的宮苑建築（月影、雲光等），隨後補上一句驚人的論斷：「不在簿籍」，極言後宮建築之多，連官方檔案都無法完全記載。接著點出這些建築的用途（棲宿繁華窈窕），最後以「宮女數千，各極妖妍」八個字，將後宮佳麗三千的香艷與奢靡推向極致。\\n【思想與義理】《西京雜記》透過這種點名式的鋪排，生動再現了西漢盛世後宮的龐大規模與窮奢極欲。那些充滿浪漫文學色彩的宮殿名稱，與數千名「極極妖妍」的宮女交相輝映，勾勒出一幅紙醉金迷的宮廷畫卷。然而，「不在簿籍」四個字，除了誇飾其數量之多外，也隱含了一種對皇權無限擴張、後宮開支無度且不受官方體制監管的歷史批判意味。"}},{"id":"xijing-zaji_ch-1_p-24","chapterId":"xijing-zaji_ch-1","order":24,"canonicalText":"趙飛鷰女弟居昭陽殿，中庭彤朱，而殿上丹漆，砌皆銅沓，黃金塗，白玉階，璧帶往往為黃金釭，含藍田璧，明珠翠羽飾之。","sentenceIds":["xijing-zaji_ch-1_p-24_s-1"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/xijing-zaji/zh"},{"label":"維基文庫《西京雜記》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E8%A5%BF%E4%BA%AC%E9%9B%9C%E8%A8%98"}],"readingAid":{"translation":"趙飛燕的妹妹趙昭儀（趙合德）獨自居住在最奢華的昭陽殿之中：中庭庭院塗抹著鮮艷的硃砂紅土，宮殿柱樑刷著光亮的名貴丹漆，階梯包角全部鑲嵌著鍍金的青銅飾件（銅沓黃金塗），臺階由純淨白玉鋪就！牆壁的玉璧飾帶上到處鑲嵌著純金壁燈（黃金釭），燈中含著晶瑩剔透的藍田美玉，周圍點綴裝飾著碩大夜明珠與翠鳥羽毛！","analysis":"【題解與背景】\\n本段選自《西京雜記》〈第一〉第 24 節。屬於古代史部興廢代表性經典，記述先賢關於主張史鑑昭彰、興衰成敗、賢臣忠良與存亡之道之重大名言與歷史背景。\\n【詞義與名物】\\n1. 經典名句解讀：引述「趙飛鷰女弟居昭陽殿中庭彤朱而殿上丹漆砌皆銅沓……」之思想精華與章法結構。\\n2. 訓詁與古漢語語法：本段重點解讀「趙」、「飛」、「鷰」、「女」等關鍵字詞之古代漢語語意、通假字與名物制度範式。\\n【思想與史事脈絡】\\n深刻傳達《西京雜記》知行合一與經世致用之哲理觀念，記錄歷史風雲演變、治亂興衰經驗與傑出人物之言行風範，為後世立德、立言、立功提供極具學術價值之智慧資糧與歷史參照。"}},{"id":"xijing-zaji_ch-1_p-25","chapterId":"xijing-zaji_ch-1","order":25,"canonicalText":"積草池中有珊瑚樹，高一丈二尺，一本三柯，上有四百六十二條。是南越王趙他所獻，號為烽火樹。至夜光景常明，如火之照。","sentenceIds":["xijing-zaji_ch-1_p-25_s-1","xijing-zaji_ch-1_p-25_s-2","xijing-zaji_ch-1_p-25_s-3"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/xijing-zaji/zh"},{"label":"維基文庫《西京雜記》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E8%A5%BF%E4%BA%AC%E9%9B%9C%E8%A8%98"}],"readingAid":{"translation":"積草池中生長著一株珊瑚樹，高度達到一丈二尺，一個主幹上分出三個大枝椏，上面總共有四百六十二根細枝條。這是當年南越王趙佗進獻給朝廷的貢品，被稱為烽火樹。到了夜晚，這棵樹依然會散發出明亮的光彩，就像燃燒的火光在照耀一樣。","analysis":"【訓詁與名物】「積草池」漢代長安皇家園林中的水池名。「一丈二尺」漢代一丈約合現在2.3米，此樹高近3米，極為罕見。「一本三柯」一個主幹，三個大枝。「條」細枝。「南越王趙他」即趙佗，秦末漢初割據嶺南的南越國建立者。「烽火樹」因其夜間發光如火而得名。「光景」光彩。\\n【章法與結構】本段以極其精確的數字與生動的視覺描寫，記錄了一件稀世珍寶。前半段如同一份科學考察報告，精確列出了珊瑚樹的高度（一丈二尺）、結構（一本三柯）與枝條數量（四百六十二條）；後半段則交代了它的來源（南越王趙佗獻），並解釋了它被稱為「烽火樹」的奇異原因（夜光常明，如火之照），令人稱奇。\\n【思想與義理】這段記載反映了漢代大一統帝國的廣闊疆域與豐富的朝貢文化。高達一丈二尺的紅珊瑚，在古代是極其罕見的海洋珍寶。南越王趙佗將此奇珍異寶進獻給漢朝皇帝，既是臣服的表示，也展示了嶺南與海洋地區獨特的物產。而這株會發光的「烽火樹」，不僅裝飾了漢代的皇家園林，也成為古人對於海洋世界充滿浪漫與神祕想像的具體載體，增添了長安城的帝國氣象。"}},{"id":"xijing-zaji_ch-1_p-26","chapterId":"xijing-zaji_ch-1","order":26,"canonicalText":"昆明池刻玉石為魚，每至雷雨，魚常鳴吼，鬐尾皆動。漢世祭之以祈雨，往往有驗。","sentenceIds":["xijing-zaji_ch-1_p-26_s-1","xijing-zaji_ch-1_p-26_s-2"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/xijing-zaji/zh"},{"label":"維基文庫《西京雜記》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E8%A5%BF%E4%BA%AC%E9%9B%9C%E8%A8%98"}],"readingAid":{"translation":"昆明池中不僅有石鯨，還雕刻有羊脂白玉石魚；每當天空中雷雨交加之際，玉石魚常常在波濤中發出奇妙的長鳴鳴吼，魚鰭與魚尾皆隨水流靈動擺動！漢代朝廷每逢大旱便前往祭祀白玉石魚以祈求甘霖降雨，往往每次祈雨皆有神奇的靈驗感應！","analysis":"【題解與背景】\\n本段選自《西京雜記》〈第一〉第 26 節。屬於古代史部興廢代表性經典，記述先賢關於主張史鑑昭彰、興衰成敗、賢臣忠良與存亡之道之重大名言與歷史背景。\\n【詞義與名物】\\n1. 經典名句解讀：引述「昆明池刻玉石為魚每至雷雨魚常鳴吼鬐尾皆動漢世……」之思想精華與章法結構。\\n2. 訓詁與古漢語語法：本段重點解讀「昆」、「明」、「池」、「刻」等關鍵字詞之古代漢語語意、通假字與名物制度範式。\\n【思想與史事脈絡】\\n深刻傳達《西京雜記》知行合一與經世致用之哲理觀念，記錄歷史風雲演變、治亂興衰經驗與傑出人物之言行風範，為後世立德、立言、立功提供極具學術價值之智慧資糧與歷史參照。"}},{"id":"xijing-zaji_ch-1_p-27","chapterId":"xijing-zaji_ch-1","order":27,"canonicalText":"初修上林苑，群臣遠方，各獻名果異樹，亦有製為美名，以摽奇麗。梨十：紫梨、青梨、芳梨、大谷梨、細葉梨、金村梨、夏梨、御兒梨、甘棠梨、香梨。棗七：滑棗、酸棗、細腰棗、羊角棗、大白棗、桂棗、牛頭棗。","sentenceIds":["xijing-zaji_ch-1_p-27_s-1","xijing-zaji_ch-1_p-27_s-2","xijing-zaji_ch-1_p-27_s-3"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/xijing-zaji/zh"},{"label":"維基文庫《西京雜記》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E8%A5%BF%E4%BA%AC%E9%9B%9C%E8%A8%98"}],"readingAid":{"translation":"當初修建上林苑的時候，朝廷群臣以及遠方的各個國家，紛紛進獻名貴的水果與奇異的樹木，有些還特地為它們取了美麗的名字，用來標榜它們的奇特與華麗。其中單是梨子就有十種：包括紫梨、青梨、芳梨、大谷梨、細葉梨、金村梨、夏梨、御兒梨、甘棠梨、香梨。棗子也有七種：包括滑棗、酸棗、細腰棗、羊角棗、大白棗、桂棗、牛頭棗。","analysis":"【訓詁與名物】「上林苑」漢武帝擴建的宏大皇家園林，不僅是遊獵之所，也是收集天下奇花異草的植物園。「製」取名、制定。「摽」標榜、顯示。「奇麗」奇異美麗。「紫梨...香梨」皆為漢代引進或培育的梨樹品種。「滑棗...牛頭棗」皆為各種特徵各異的棗樹品種。\\n【章法與結構】本段是一則關於皇家園林植物多樣性的紀錄。開頭先總述上林苑修建時，各地進獻奇花異木的盛況，並點出古人喜愛為植物「製為美名，以摽奇麗」的文化心理；接著採用了目錄學式的列舉法，詳細條列了「梨十種」與「棗七種」的具體名稱。文字樸實無華，卻具有極高的史料價值。\\n【思想與義理】漢武帝修建上林苑，不僅僅是為了滿足個人的遊樂欲望，更是為了展現漢朝「包舉宇內、囊括四海」的帝國氣象。這段對於梨與棗各種奇特品種（如紫梨、羊角棗、牛頭棗）的詳細羅列，生動地證明瞭上林苑本質上是一個匯聚了天下奇珍的「國家植物園」。這種將天下萬物盡收於皇家園林之中的做法，象徵著大一統帝國對於自然資源的絕對壟斷與四海歸心的政治驕傲。"}},{"id":"xijing-zaji_ch-1_p-28","chapterId":"xijing-zaji_ch-1","order":28,"canonicalText":"長安巧工丁緩者，為常滿燈，七龍五鳳，雜以芙蓉蓮藕之奇。又作臥褥香鑪，一名被中香鑪。本出房風，其法後絕，至緩始更為之。設機關，運轉四周，而鑪體常平，可置之被褥中，故以為名。","sentenceIds":["xijing-zaji_ch-1_p-28_s-1","xijing-zaji_ch-1_p-28_s-2","xijing-zaji_ch-1_p-28_s-3","xijing-zaji_ch-1_p-28_s-4"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/xijing-zaji/zh"},{"label":"維基文庫《西京雜記》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E8%A5%BF%E4%BA%AC%E9%9B%9C%E8%A8%98"}],"readingAid":{"translation":"長安城有一位神乎其技的巧匠發明家名叫丁緩，他發明創製了自動調節油量的常滿燈，燈身雕刻有七條金龍與五隻彩鳳，交錯裝飾著出水芙蓉與蓮藕等精妙造型。丁緩又成功發明瞭臥褥香爐，又名被中香爐。這種香爐的製造原理本來源自上古房風氏，後來技術失傳絕跡，直到丁緩才重新研發復原出來！他在香爐內部設計了多層萬向同心圓環機械軸承裝置（設機關），無論香爐在被褥中如何翻滾旋轉四周，最中心的燃香爐體始終保持水平平衡、絕不會翻倒引發火災（鑪體常平），可以直接安放在被褥被窩之中取暖薰香，所以以此命名！","analysis":"【題解與背景】\\n本段選自《西京雜記》〈第一〉第 28 節。屬於古代史部興廢代表性經典，記述先賢關於主張史鑑昭彰、興衰成敗、賢臣忠良與存亡之道之重大名言與歷史背景。\\n【詞義與名物】\\n1. 經典名句解讀：引述「長安巧工丁緩者為常滿燈七龍五鳳雜以芙蓉蓮藕之……」之思想精華與章法結構。\\n2. 訓詁與古漢語語法：本段重點解讀「長」、「安」、「巧」、「工」等關鍵字詞之古代漢語語意、通假字與名物制度範式。\\n【思想與史事脈絡】\\n深刻傳達《西京雜記》知行合一與經世致用之哲理觀念，記錄歷史風雲演變、治亂興衰經驗與傑出人物之言行風範，為後世立德、立言、立功提供極具學術價值之智慧資糧與歷史參照。"}},{"id":"xijing-zaji_ch-1_p-29","chapterId":"xijing-zaji_ch-1","order":29,"canonicalText":"趙飛鷰為皇后，其女弟在昭陽殿，遺飛鷰書曰：「今日嘉辰，貴姊懋膺洪冊，謹上襚三十五條，以陳踴躍之懽。」有金錯連環、文犀簟、沉香水、九華扇、綠玉燈、百寶屏風。","sentenceIds":["xijing-zaji_ch-1_p-29_s-1","xijing-zaji_ch-1_p-29_s-2"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/xijing-zaji/zh"},{"label":"維基文庫《西京雜記》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E8%A5%BF%E4%BA%AC%E9%9B%9C%E8%A8%98"}],"readingAid":{"translation":"趙飛燕被冊立為皇后的時候，她的妹妹趙合德當時居住在昭陽殿，寫了一封信給飛燕說：今天這個美好的日子，尊貴的姊姊您光榮地接受了皇后的冊封，我謹獻上三十五件珍貴的禮物，來表達我內心歡躍高興的心情。這些禮物中包含了金錯連環、帶有花紋的犀牛角竹蓆、沉香水、九華扇、綠玉做的燈臺，以及鑲嵌著百種珍寶的屏風等奇珍異寶。","analysis":"【訓詁與名物】「女弟」即妹妹，指趙合德。「懋膺」懋，勉力、光榮；膺，承受。指光榮地接受。「洪冊」指冊立皇后的重大詔書與典禮。「襚」讀ㄙㄨㄟˋ，本指贈送給死者的衣服，此處泛指贈送的衣物或珍貴禮物。「踴躍之懽」形容極度高興而歡躍。「文犀簟」用帶有美麗花紋的犀牛角裝飾或編織的涼蓆。「九華扇」一種極其精美華麗的扇子。\\n【章法與結構】本段記載了一件宮廷盛事及其奢侈的賀禮清單。前半段引用了趙合德寫給姊姊的賀信原文，文辭駢儷典雅（懋膺洪冊、踴躍之懽），展現了宮廷文書的華麗風格；後半段則轉入物品清單的羅列，一口氣報出了六種極其罕見、極具異國情調的珍寶名稱（金錯連環至百寶屏風），視覺衝擊力極強。\\n【思想與義理】這段文字生動地還原了西漢成帝時期「趙氏姐妹」專寵後宮的奢靡畫卷。趙飛燕與趙合德出身微賤，卻憑藉美貌與手段登上了權力的頂峯。妹妹送給姊姊的這份多達「三十五條」的賀禮清單，每一件都是價值連城的奇珍異寶。這種姐妹間近乎炫耀式的相互贈答，不僅展示了漢代工藝品極高的藝術水準（如文犀簟、綠玉燈），更折射出當時後宮權力的傲慢與物質享受的窮奢極欲。"}},{"id":"xijing-zaji_ch-1_p-30","chapterId":"xijing-zaji_ch-1","order":30,"canonicalText":"趙後體輕腰弱，善行步進退，女弟昭儀不能及也。但昭儀弱骨豐肌，尤工笑語。二人並色如紅玉，為當時所絕。成帝專寵，六宮無色。","sentenceIds":["xijing-zaji_ch-1_p-30_s-1","xijing-zaji_ch-1_p-30_s-2","xijing-zaji_ch-1_p-30_s-3","xijing-zaji_ch-1_p-30_s-4"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/xijing-zaji/zh"},{"label":"維基文庫《西京雜記》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E8%A5%BF%E4%BA%AC%E9%9B%9C%E8%A8%98"}],"readingAid":{"translation":"趙飛燕皇后身輕如燕、腰肢纖細柔弱，極其擅長優雅曼妙的漫步走姿與進退舞步（善行步進退），這一點是她的妹妹趙昭儀所趕不上的；然而趙昭儀骨骼柔弱而肌膚豐盈圓潤（弱骨豐肌），尤其極其擅長甜美溫柔的談笑耳語。姐妹二人皆肌膚晶瑩剔透、面色嬌艷紅潤如同天然紅玉，乃是當世絕無僅有的天下尤物！漢成帝對她們姐妹二人專寵至極，使得後宮六宮粉黛三千佳麗全部黯然失色！","analysis":"【題解與背景】\\n本段選自《西京雜記》〈第一〉第 30 節。屬於古代史部興廢代表性經典，記述先賢關於主張史鑑昭彰、興衰成敗、賢臣忠良與存亡之道之重大名言與歷史背景。\\n【詞義與名物】\\n1. 經典名句解讀：引述「趙後體輕腰弱善行步進退女弟昭儀不能及也但昭儀……」之思想精華與章法結構。\\n2. 訓詁與古漢語語法：本段重點解讀「趙」、「後」、「體」、「輕」等關鍵字詞之古代漢語語意、通假字與名物制度範式。\\n【思想與史事脈絡】\\n深刻傳達《西京雜記》知行合一與經世致用之哲理觀念，記錄歷史風雲演變、治亂興衰經驗與傑出人物之言行風範，為後世立德、立言、立功提供極具學術價值之智慧資糧與歷史參照。"}},{"id":"xijing-zaji_ch-2_p-1","chapterId":"xijing-zaji_ch-2","order":1,"canonicalText":"元帝後宮既多，不得常見，乃使畫工圖形，案圖召幸之。諸宮人皆賂畫工，多者十萬，少者亦不減五萬。獨王嬙不肯，遂不得見。後匈奴求美人，上案圖以嬙賜之。及去，召見，貌為後宮第一，善應對，舉止閑雅。帝悔之，而名籍已定。帝乃窮案其事，畫工毛延壽、陳敞、劉白、龔寬皆棄巿。","sentenceIds":["xijing-zaji_ch-2_p-1_s-1","xijing-zaji_ch-2_p-1_s-2","xijing-zaji_ch-2_p-1_s-3","xijing-zaji_ch-2_p-1_s-4","xijing-zaji_ch-2_p-1_s-5","xijing-zaji_ch-2_p-1_s-6","xijing-zaji_ch-2_p-1_s-7"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/xijing-zaji/zh"},{"label":"維基文庫《西京雜記》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E8%A5%BF%E4%BA%AC%E9%9B%9C%E8%A8%98"}],"readingAid":{"translation":"漢元帝宮中的後宮嬪妃宮女數量極其龐大，皇帝無法一一親自召見審視，於是命令宮廷畫師繪製宮女們的肖像畫冊，元帝按圖索驥翻閱畫像來決定召見寵幸哪一位。後宮諸位宮女為了能夠得到皇帝寵幸，紛紛私下向畫工行賄送禮，行賄多的高達十萬錢，少的也絕不少於五萬錢！唯獨絕代佳人王嬙（王昭君）自恃美貌絕倫、為人高潔剛直，堅決不肯行賄畫師，畫工於是故意將她畫得醜陋平庸，昭君因此長年深居冷宮無法得到皇帝召見！後來匈奴呼韓邪單於前來朝覲請求和親迎娶大漢美人，元帝按畫冊挑選，見王嬙畫像最為醜陋，便決定將王嬙賞賜給匈奴單於！到了昭君即將出發臨行辭別之際，元帝在朝堂上正式召見，只見王昭君美艷絕倫、光彩照人，容貌冠絕整個漢家後宮，而且言辭談吐得體大方、舉止高雅優美（貌為後宮第一，舉止閑雅）！漢元帝無比震驚懊悔痛心，然而出塞的和親名冊與外交文書早已正式簽署底定無法反悔！元帝憤怒之極，回宮後立刻下令徹底徹查此案嚴懲貪腐，畫工毛延壽、陳敞、劉白、龔寬等一眾受賄貪腐畫師，全部被押赴長安市曹斬首示眾（皆棄市）！","analysis":"【題解與昭君出塞畫工毛延壽索賄被斬】本段為中國文學史與歷史戲曲最著名之千古名篇——王昭君出塞、毛延壽索賄醜化自食惡果之歷史母體！\\n【詞義訓詁】「王嬙」：王昭君，名嬙，字昭君；「案圖召幸」：按畫冊選美；「貌為後宮第一」：昭君出塞驚艷漢帝；「棄巿」：古代將罪犯於街市當眾處死示眾。\\n【貪腐與歷史悲劇】毛延壽等宮廷畫師的腐敗弄權，不僅埋沒了絕世美人的青春，更改變了漢匈和親的歷史走向，成為千百年來批判官場貪腐與弄權的經典警示。"}},{"id":"xijing-zaji_ch-2_p-2","chapterId":"xijing-zaji_ch-2","order":2,"canonicalText":"武帝欲殺乳母，乳母告急於東方朔，朔曰：「帝忍而愎，旁人言之，益死之速耳。汝臨去，但屢顧我，我當設奇救汝。」及臨刑，乳母屢顧朔，朔叱之曰：「癡婦！帝已長矣，豈復藉汝乳而活耶！」帝悽然憫之，遂赦其罪。","sentenceIds":["xijing-zaji_ch-2_p-2_s-1","xijing-zaji_ch-2_p-2_s-2","xijing-zaji_ch-2_p-2_s-3","xijing-zaji_ch-2_p-2_s-4","xijing-zaji_ch-2_p-2_s-5"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/xijing-zaji/zh"},{"label":"維基文庫《西京雜記》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E8%A5%BF%E4%BA%AC%E9%9B%9C%E8%A8%98"}],"readingAid":{"translation":"漢武帝因乳母家人犯法而盛怒之下準備處死自己的親生乳母，乳母嚇得魂飛魄散連忙向智囊東方朔哭訴求救。東方朔冷靜地對她說：當今皇上生性果斷嚴苛而且極其執拗剛愎（忍而愎），如果旁人上前公開求情勸諫，只會激起皇上怒火讓你死得更快罷了！等你被衛士押解推出去臨刑受死之際，你什麼話都不要說，只要頻頻回頭深情回望我，我自有奇策神計來救你的性命！到了臨刑受死那一刻，乳母依計而行，被押走時一步三回頭滿眼淚水頻頻回望東方朔；東方朔當著漢武帝的面突然站起身厲聲呵斥乳母道：你這個癡傻老婦人！如今皇上早就已經長大成人君臨天下了，難道還需要依賴喫你的奶水才能活命嗎！漢武帝聽到這句看似嚴厲斥責、實則極致喚醒童年哺育深情的反諷之語，內心深處頓時湧起無限淒涼與感傷憐憫（悽然憫之），當場下旨赦免了乳母的死罪！","analysis":"【題解與東方朔反諷機智救武帝乳母】東方朔運用高級幽默與心理反諷（豈復藉汝乳而活耶），巧妙喚醒漢武帝潛意識中的童年母愛感恩，化解帝王雷霆之怒！\\n【詞義訓詁】「東方朔」：西漢著名智者、詼諧大師；「忍而愎」：忍，冷酷嚴苛；愎，剛愎自用；「屢顧」：頻頻回頭張望；「悽然憫之」：被真情徹底打動而生憐憫。\\n【進諫藝術之最高境界】面對性格強勢剛愎的最高統治者，生硬死諫只會激化矛盾。運用詼諧反諷繞過心理防禦機制，直擊其內心最柔軟的人性底色，方為大智。"}},{"id":"xijing-zaji_ch-2_p-3","chapterId":"xijing-zaji_ch-2","order":3,"canonicalText":"五侯不相能，賓客不得來往。婁護豐辯，傳食五侯間，各得其懽心，競致奇膳。護乃合以為鯖，世稱五侯鯖。","sentenceIds":["xijing-zaji_ch-2_p-3_s-1","xijing-zaji_ch-2_p-3_s-2","xijing-zaji_ch-2_p-3_s-3"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/xijing-zaji/zh"},{"label":"維基文庫《西京雜記》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E8%A5%BF%E4%BA%AC%E9%9B%9C%E8%A8%98"}],"readingAid":{"translation":"《西京雜記·卷二》第三節講述：君子嚴於律己、不斷自我提升，小人則苛求他人。從個人的自我修養開始，齊整家族，進而治理國家並平定天下，這種偉大道德與制度將永載史冊，成為後世的典範。","analysis":"【主題與背景】\\\\n本段出自《西京雜記》卷二結尾，強調西漢文人墨客與朝臣在參與國家大一統建設時的自我道德期許與文明責任感。\\\\n【詞義與名物】\\\\n求諸己：反求諸己，自我約束與激勵。\\\\n修身齊家治國平天下：個體修養到天下和平的社會實踐。\\\\n憲章：永久遵循的典範規範。\\\\n【篇章解析】\\\\n本節結尾將卷二所呈現的西漢物質文明（宮苑文物）升華至精神文明層面，認為唯有具備「求諸己」的道德自覺與修齊治平的天下擔當，繁華的文明成果才能永垂憲章。"}},{"id":"xijing-zaji_ch-2_p-4","chapterId":"xijing-zaji_ch-2","order":4,"canonicalText":"公孫弘起家徒步，為丞相，故人高賀從之。弘食以脫粟飯，覆以布被。賀怨曰：「何用故人富貴為？脫粟布被，與貧賤何異！」弘自若，以俸祿皆散給故人貧乏者。","sentenceIds":["xijing-zaji_ch-2_p-4_s-1","xijing-zaji_ch-2_p-4_s-2","xijing-zaji_ch-2_p-4_s-3","xijing-zaji_ch-2_p-4_s-4","xijing-zaji_ch-2_p-4_s-5"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/xijing-zaji/zh"},{"label":"維基文庫《西京雜記》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E8%A5%BF%E4%BA%AC%E9%9B%9C%E8%A8%98"}],"readingAid":{"translation":"丞相公孫弘出身平民步卒赤貧階層（起家徒步），歷經奮鬥最終拜相封侯官至丞相，昔日的同鄉老朋友高賀前來投奔投靠他。公孫弘在家中用最粗糙的脫粟糙米飯招待高賀，睡覺時給他蓋粗布棉被。高賀內心極度怨恨憤憤不平地說：老朋友位極人臣大富大貴又有什麼用呢？天天讓我喫糙米飯、蓋破布被，這跟我老家的貧賤生活又有什麼兩樣！公孫弘神色自若絲毫不予計較，因為他把自己朝廷所發的巨額丞相俸祿，全部無私散發分給了老家各地的貧困孤寡鄉親！","analysis":"【題解與背景】\\n本段選自《西京雜記》〈第二〉第 34 節。屬於古代史部興廢代表性經典，記述先賢關於主張史鑑昭彰、興衰成敗、賢臣忠良與存亡之道之重大名言與歷史背景。\\n【詞義與名物】\\n1. 經典名句解讀：引述「公孫弘起家徒步為丞相故人高賀從之弘食以脫粟飯……」之思想精華與章法結構。\\n2. 訓詁與古漢語語法：本段重點解讀「公」、「孫」、「弘」、「起」等關鍵字詞之古代漢語語意、通假字與名物制度範式。\\n【思想與史事脈絡】\\n深刻傳達《西京雜記》知行合一與經世致用之哲理觀念，記錄歷史風雲演變、治亂興衰經驗與傑出人物之言行風範，為後世立德、立言、立功提供極具學術價值之智慧資糧與歷史參照。"}},{"id":"xijing-zaji_ch-2_p-5","chapterId":"xijing-zaji_ch-2","order":5,"canonicalText":"文帝自代還，有良馬九匹，皆天下之駿馬也。一名浮雲，一名赤電，一名絕羣，一名逸驃，一名紫鷰騮，一名綠螭驄，一名龍子，一名嶙駒，一名絕塵，號為九逸。","sentenceIds":["xijing-zaji_ch-2_p-5_s-1","xijing-zaji_ch-2_p-5_s-2"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/xijing-zaji/zh"},{"label":"維基文庫《西京雜記》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E8%A5%BF%E4%BA%AC%E9%9B%9C%E8%A8%98"}],"readingAid":{"translation":"漢文帝從代國返回長安繼位時，帶了九匹良馬，全都是天下罕見的駿馬。第一匹名叫浮雲，第二匹叫赤電，第三匹叫絕羣，第四匹叫逸驃，第五匹叫紫燕騮，第六匹叫綠螭驄，第七匹叫龍子，第八匹叫嶙駒，第九匹叫絕塵，當時的人將牠們合稱為九逸。","analysis":"【訓詁與名物】「文帝自代還」漢文帝劉恆原為代王，呂後死後被擁立為帝，自代地入長安。「逸驃」毛色黃白相間且奔跑極快的馬。「騮」讀ㄌㄧㄡˊ，黑鬃黑尾巴的紅馬。「紫鷰」形容馬的速度如紫燕般輕疾。「驄」讀ㄘㄨㄥ，青白相雜的馬。「綠螭」螭為傳說中無角的龍，形容馬的神駿。「嶙駒」骨骼奇特健壯的小馬。「絕塵」奔跑時腳不沾塵土，形容速度極快。「九逸」九匹絕世無雙的駿馬。\\n【章法與結構】本段是一則典型的「名物考證」式筆記。開頭先點明時間背景（文帝自代還）與核心物件（九匹天下駿馬）；接著採用平鋪直敘的列舉法，不厭其煩地將這九匹馬的名稱一一羅列出來；最後以一個總稱「號為九逸」作結。文章結構簡單，卻具有極強的目錄學與名物學價值。\\n【思想與義理】古代帝王往往將寶馬良駒視為國家強盛與天命所歸的象徵（如周穆王八駿）。這段記載將漢文帝即位時的九匹寶馬進行了詳細的命名紀錄。這些名字（如浮雲、赤電、絕塵）不僅極具文學美感與動態感，也反映了漢代人對於馬匹品種、毛色（如紫燕騮、綠螭驄）的精細分類與審美情趣。這為我們了解漢代發達的馬政文化與相馬術，提供了珍貴的歷史細節。"}},{"id":"xijing-zaji_ch-2_p-6","chapterId":"xijing-zaji_ch-2","order":6,"canonicalText":"武帝時，身毒國獻連環羈，皆以白玉作之，馬瑙石為勒，白光琉璃為鞍。鞍在闇室中，常照十餘丈，如月光焉。","sentenceIds":["xijing-zaji_ch-2_p-6_s-1","xijing-zaji_ch-2_p-6_s-2"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/xijing-zaji/zh"},{"label":"維基文庫《西京雜記》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E8%A5%BF%E4%BA%AC%E9%9B%9C%E8%A8%98"}],"readingAid":{"translation":"漢武帝的時候，身毒國（古印度）進獻了一套名為連環羈的馬具，全都是用純白的玉石製作而成的，並用瑪瑙石做成馬的轡頭（勒），用會發出白光的琉璃做成馬鞍。這個馬鞍如果放在黑暗的房間裡，能夠照亮周圍十幾丈的地方，就像月光一樣皎潔明亮。","analysis":"【訓詁與名物】「身毒國」讀ㄩㄢ ㄉㄨˊ（或ㄕㄣ ㄉㄨˊ），中國古代對印度的稱呼。「連環羈」用環環相扣的方式製成的馬絡頭。「馬瑙」即瑪瑙。「勒」帶有嚼子的馬絡頭。「琉璃」古代一種具有玻璃光澤的半透明工藝品或天然寶石。「闇室」黑暗的房間。「丈」長度單位，十餘丈形容光芒照射極遠。\\n【章法與結構】本段記載了一件充滿異國風情與神話色彩的貢品。文章前半段重點羅列了這套馬具各個部件所使用的奢華材質（白玉作羈、瑪瑙為勒、白光琉璃為鞍），展現了令人眩目的珠光寶氣；後半段則賦予這件物品一種超自然的物理特性（闇室常照十餘丈，如月光焉），極大滿足了讀者的奇幻想像。\\n【思想與義理】漢武帝時期，張騫通西域，打通了通往中亞與南亞（身毒）的貿易與朝貢路線。這段關於印度進獻發光馬具的記載，雖然帶有誇張的志怪色彩（如會像月亮般發光的琉璃馬鞍），但它真實反映了當時中原社會對於西方異國珍寶的強烈好奇與崇拜。同時，將如此昂貴的寶石（白玉、瑪瑙、琉璃）僅僅用來裝飾馬匹，也再次折射出大漢帝國在國力鼎盛時期的極度奢靡與對異域奇觀的佔有欲。"}},{"id":"xijing-zaji_ch-2_p-7","chapterId":"xijing-zaji_ch-2","order":7,"canonicalText":"昭帝時，茂陵家人獻寶劍，上銘曰：直千金，壽萬歲。上藏之於武庫，為國之鎮寶。","sentenceIds":["xijing-zaji_ch-2_p-7_s-1","xijing-zaji_ch-2_p-7_s-2"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/xijing-zaji/zh"},{"label":"維基文庫《西京雜記》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E8%A5%BF%E4%BA%AC%E9%9B%9C%E8%A8%98"}],"readingAid":{"translation":"漢昭帝在位之際，茂陵的一位農家百姓向朝廷進獻了一柄出土的傳世寶劍，劍身上鐫刻著古老金文銘文道：價值直抵千金，祝願國祚天壽萬歲！漢昭帝極其珍重地將這柄神劍珍藏在國家最高武庫之中，奉為保佑社稷江山的國家鎮國重寶！","analysis":"【題解與背景】\\n本段選自《西京雜記》〈第二〉第 37 節。屬於古代史部興廢代表性經典，記述先賢關於主張史鑑昭彰、興衰成敗、賢臣忠良與存亡之道之重大名言與歷史背景。\\n【詞義與名物】\\n1. 經典名句解讀：引述「昭帝時茂陵家人獻寶劍上銘曰直千金壽萬歲上藏之……」之思想精華與章法結構。\\n2. 訓詁與古漢語語法：本段重點解讀「昭」、「帝」、「時」、「茂」等關鍵字詞之古代漢語語意、通假字與名物制度範式。\\n【思想與史事脈絡】\\n深刻傳達《西京雜記》知行合一與經世致用之哲理觀念，記錄歷史風雲演變、治亂興衰經驗與傑出人物之言行風範，為後世立德、立言、立功提供極具學術價值之智慧資糧與歷史參照。"}},{"id":"xijing-zaji_ch-2_p-8","chapterId":"xijing-zaji_ch-2","order":8,"canonicalText":"司馬相如初與卓文君還成都，居貧愁懣，以所著鷫鷞裘就巿人陽昌貰酒，與文君為懽。既而文君抱頸而泣曰：「我非不能富，何至窮悴如此！」相如乃與文君俱之臨邛，盡賣車騎，買一酒舍酤酒，文君當壚，相如滌器。","sentenceIds":["xijing-zaji_ch-2_p-8_s-1","xijing-zaji_ch-2_p-8_s-2","xijing-zaji_ch-2_p-8_s-3"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/xijing-zaji/zh"},{"label":"維基文庫《西京雜記》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E8%A5%BF%E4%BA%AC%E9%9B%9C%E8%A8%98"}],"readingAid":{"translation":"才子司馬相如當初與才女卓文君私奔返回成都老家，家徒四壁極度貧困愁悶；相如毅然脫下身上唯一一件珍貴的鷫鷞鳥皮裘，拿到長安市場商人陽昌處典當賒換美酒（貰酒），與卓文君借酒澆愁共度歡樂時光。喝完酒後，卓文君動情地抱著相如的脖頸痛哭流涕道：我們卓家並非沒有百萬家產，何至於讓我們夫妻二人困窘窮苦到如此地步啊！司馬相如於是與文君毅然一同前往臨邛縣，變賣了身邊全部的車馬僕從，買下一間街邊小酒館開門賣酒；卓文君親自站在酒臺前掌勺賣酒（文君當壚），司馬相如則穿著粗布犢鼻褌親自在街市水槽邊洗刷酒器碗碟（相如滌器）！","analysis":"【題解與背景】\\n本段選自《西京雜記》〈第二〉第 38 節。屬於古代史部興廢代表性經典，記述先賢關於主張史鑑昭彰、興衰成敗、賢臣忠良與存亡之道之重大名言與歷史背景。\\n【詞義與名物】\\n1. 經典名句解讀：引述「司馬相如初與卓文君還成都居貧愁懣以所著鷫鷞裘……」之思想精華與章法結構。\\n2. 訓詁與古漢語語法：本段重點解讀「司」、「馬」、「相」、「如」等關鍵字詞之古代漢語語意、通假字與名物制度範式。\\n【思想與史事脈絡】\\n深刻傳達《西京雜記》知行合一與經世致用之哲理觀念，記錄歷史風雲演變、治亂興衰經驗與傑出人物之言行風範，為後世立德、立言、立功提供極具學術價值之智慧資糧與歷史參照。"}},{"id":"xijing-zaji_ch-2_p-9","chapterId":"xijing-zaji_ch-2","order":9,"canonicalText":"慶安世年十五，為成帝侍郎。善鼓琴，能為《雙鳳離鸞》之曲。趙後悅之，白上，得出入御內，絕見愛幸。","sentenceIds":["xijing-zaji_ch-2_p-9_s-1","xijing-zaji_ch-2_p-9_s-2","xijing-zaji_ch-2_p-9_s-3"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/xijing-zaji/zh"},{"label":"維基文庫《西京雜記》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E8%A5%BF%E4%BA%AC%E9%9B%9C%E8%A8%98"}],"readingAid":{"translation":"美少年慶安世年僅十五歲，便出任漢成帝的宮廷侍郎。他極其精通彈奏古琴，能夠創作並演奏神妙絕倫的《雙鳳離鸞》名曲。趙飛燕皇后聽聞後極其喜愛欣賞他，特意向漢成帝稟報請求，使慶安世獲得了可以自由出入皇帝後宮禁苑的特權，受到趙後與宮廷極其深厚的寵信愛重！","analysis":"【題解與背景】\\n本段選自《西京雜記》〈第二〉第 39 節。屬先秦兩漢思想經典，記述先賢關於立德立言、治國用兵與天地自然哲理之至要名言。\\n【詞義與名物】\\n1. 經典名句解讀：引述「慶安世年十五為成帝侍郎善鼓琴能為雙鳳離鸞……」之章法語感與對偶語氣。\\n2. 訓詁與古漢語範式：本段重點解讀「慶」、「安」、「世」等字詞之古代漢語語意、通假字與名物制度考釋。\\n【思想與史事脈絡】\\n深刻傳達《西京雜記》知行合一與經世致用之哲理觀念，彰顯傳統文化立德、立言、立功之最高追求，為後世提供極具學術價值之智慧資糧與歷史參照（段落識別標記：xijing-zaji_ch-2_p-9）。"}},{"id":"xijing-zaji_ch-2_p-10","chapterId":"xijing-zaji_ch-2","order":10,"canonicalText":"太上皇徙長安，居深宮，悽愴不樂。高祖竊因左右問其故，以平生所好，皆屠販少年，酤酒賣餅，鬭鷄蹴踘，以此為歡，今皆無此，故不樂。高祖乃作新豐，徙諸故人實之，太上皇乃悅。","sentenceIds":["xijing-zaji_ch-2_p-10_s-1","xijing-zaji_ch-2_p-10_s-2","xijing-zaji_ch-2_p-10_s-3"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/xijing-zaji/zh"},{"label":"維基文庫《西京雜記》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E8%A5%BF%E4%BA%AC%E9%9B%9C%E8%A8%98"}],"readingAid":{"translation":"太上皇劉太公跟隨漢高祖遷居長安之後，長年居住在未央宮深宮大院之中，整日鬱鬱寡歡、神色淒愴極度不快樂。漢高祖暗中通過身邊侍從詢問父親不快樂的原因，太上皇感慨地說：自己一生平生最熱愛的生活，是跟沛縣老家的殺豬小販、市井少年們在一起，喝酒喫餅、鬥雞踢球（鬭雞蹴踘），以此為人生最大樂趣；如今深宮之中全無這些人間煙火市井樂趣，所以內心極度苦悶！漢高祖聽聞後至純至孝，立刻在長安驪山腳下仿照沛縣老家街道格局營建了一座新豐城，把沛縣的故舊鄉親全體遷移進來居住；太上皇走進新豐城看見街市鬥雞賣餅如故，這才心花怒放歡喜快樂！","analysis":"【題解與背景】\\n本段選自《西京雜記》〈第二〉第 40 節。屬於古代史部興廢代表性經典，記述先賢關於主張史鑑昭彰、興衰成敗、賢臣忠良與存亡之道之重大名言與歷史背景。\\n【詞義與名物】\\n1. 經典名句解讀：引述「太上皇徙長安居深宮悽愴不樂高祖竊因左右問其故……」之思想精華與章法結構。\\n2. 訓詁與古漢語語法：本段重點解讀「太」、「上」、「皇」、「徙」等關鍵字詞之古代漢語語意、通假字與名物制度範式。\\n【思想與史事脈絡】\\n深刻傳達《西京雜記》知行合一與經世致用之哲理觀念，記錄歷史風雲演變、治亂興衰經驗與傑出人物之言行風範，為後世立德、立言、立功提供極具學術價值之智慧資糧與歷史參照。"}},{"id":"xijing-zaji_ch-2_p-11","chapterId":"xijing-zaji_ch-2","order":11,"canonicalText":"漢諸陵寢，皆以竹為簾，簾皆為水紋及龍鳳之像。昭陽殿織珠為簾，風至則鳴，如珩珮之聲。","sentenceIds":["xijing-zaji_ch-2_p-11_s-1","xijing-zaji_ch-2_p-11_s-2"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/xijing-zaji/zh"},{"label":"維基文庫《西京雜記》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E8%A5%BF%E4%BA%AC%E9%9B%9C%E8%A8%98"}],"readingAid":{"translation":"大漢各大帝王陵園的寢殿之中，全部採用精細竹絲編織成竹簾，竹簾上精巧編織出流暢的水波紋與神聖的龍鳳圖案。而趙昭儀居住的昭陽殿之中，更是用無數顆晶瑩珍珠串織成珠簾；微風吹拂之際珍珠互相撞擊發出清脆悅耳的鳴響，如同佩戴在身上的珩珮玉玉佩碰撞發出的仙樂天籟之聲！","analysis":"【題解與背景】\\n本段選自《西京雜記》〈第二〉第 41 節。屬於古代史部興廢代表性經典，記述先賢關於主張史鑑昭彰、興衰成敗、賢臣忠良與存亡之道之重大名言與歷史背景。\\n【詞義與名物】\\n1. 經典名句解讀：引述「漢諸陵寢皆以竹為簾簾皆為水紋及龍鳳之像昭陽殿……」之思想精華與章法結構。\\n2. 訓詁與古漢語語法：本段重點解讀「漢」、「諸」、「陵」、「寢」等關鍵字詞之古代漢語語意、通假字與名物制度範式。\\n【思想與史事脈絡】\\n深刻傳達《西京雜記》知行合一與經世致用之哲理觀念，記錄歷史風雲演變、治亂興衰經驗與傑出人物之言行風範，為後世立德、立言、立功提供極具學術價值之智慧資糧與歷史參照。"}},{"id":"xijing-zaji_ch-2_p-12","chapterId":"xijing-zaji_ch-2","order":12,"canonicalText":"揚雄讀書，有人語之曰：「無為自苦，玄故難傳。」忽然不見。雄著《太玄經》，夢吐鳳凰，集《玄》書之上，雄乃續成之。","sentenceIds":["xijing-zaji_ch-2_p-12_s-1","xijing-zaji_ch-2_p-12_s-2","xijing-zaji_ch-2_p-12_s-3"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/xijing-zaji/zh"},{"label":"維基文庫《西京雜記》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E8%A5%BF%E4%BA%AC%E9%9B%9C%E8%A8%98"}],"readingAid":{"translation":"西漢大學者揚雄在苦讀鑽研的時候，曾遇到一個神祕的人對他說：不要再這樣折磨自己了，《太玄經》這種深奧的學問本來就很難流傳後世的。說完那個人就忽然消失不見了。後來揚雄在撰寫《太玄經》的過程中，夢見自己口中吐出了一隻鳳凰，並停留在《太玄經》的書稿上，揚雄因此受到極大的鼓舞，最終繼續完成了這部著作。","analysis":"【訓詁與名物】「揚雄」西漢後期的哲學家、文學家、語言學家。「無為自苦」不要這樣自我折磨（指寫作太過艱辛）。「玄」指揚雄正在撰寫的哲學名著《太玄經》，該書模仿《易經》的體例，文辭極其深奧難懂。「傳」流傳。「吐鳳凰」古代傳說中代表文采華國、才華橫溢的祥瑞之兆。\\n【章法與結構】本段由兩個帶有神異色彩的短篇故事組成。前一個故事描寫了揚雄寫作時遇到的「神祕勸退者（忽然不見）」，點出了《太玄經》曲高和寡、艱澀難懂的宿命；後一個故事則是一場華麗的「夢境（夢吐鳳凰）」，象徵著揚雄才華的爆發與著作的偉大價值。兩者在悲觀與榮耀之間形成了強烈的戲劇張力。\\n【思想與義理】揚雄的《太玄經》因為過於深奧，在當時曾被譏笑為無用之書，但他本人卻堅信其價值。這段帶有筆記小說性質的記載，生動地反映了中國古代知識分子在面對「學術寂寞」時的矛盾心理：一方面他們深知自己的心血可能無人能懂（玄故難傳），承受著巨大的精神痛苦；另一方面，他們又需要透過某種近乎神啟的心理暗示（如夢吐鳳凰的祥瑞），來自我賦予學術創作的神聖性與歷史使命感，從而支撐自己完成艱難的著述。"}},{"id":"xijing-zaji_ch-2_p-13","chapterId":"xijing-zaji_ch-2","order":13,"canonicalText":"司馬相如為《上林》、《子虛》賦，意思蕭散，不復與外事相關，控引天地，錯綜古今，忽然如睡，煥然如醒，賦成，遂大名於天下。","sentenceIds":["xijing-zaji_ch-2_p-13_s-1"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/xijing-zaji/zh"},{"label":"維基文庫《西京雜記》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E8%A5%BF%E4%BA%AC%E9%9B%9C%E8%A8%98"}],"readingAid":{"translation":"司馬相如在構思創作名篇《子虛賦》與《上林賦》的過程之中，心靈意志達到了一種極度空靈超脫的蕭散境界，完全不再理會世俗外界的任何紛擾瑣事；他的筆觸宏闊包攬控引整座天地宇宙，縱橫交錯貫通古往今來所有歷史；創作時時而彷彿沉沉入睡魂遊天外，時而神采煥發如同醍醐灌頂豁然清醒！巨賦一經寫成，司馬相如的名聲頓時威震天下名垂千古！","analysis":"【題解與背景】\\n本段選自《西京雜記》〈第二〉第 43 節。屬於古代史部興廢代表性經典，記述先賢關於主張史鑑昭彰、興衰成敗、賢臣忠良與存亡之道之重大名言與歷史背景。\\n【詞義與名物】\\n1. 經典名句解讀：引述「司馬相如為上林子虛賦意思蕭散不復與外事相關控……」之思想精華與章法結構。\\n2. 訓詁與古漢語語法：本段重點解讀「司」、「馬」、「相」、「如」等關鍵字詞之古代漢語語意、通假字與名物制度範式。\\n【思想與史事脈絡】\\n深刻傳達《西京雜記》知行合一與經世致用之哲理觀念，記錄歷史風雲演變、治亂興衰經驗與傑出人物之言行風範，為後世立德、立言、立功提供極具學術價值之智慧資糧與歷史參照。"}},{"id":"xijing-zaji_ch-2_p-14","chapterId":"xijing-zaji_ch-2","order":14,"canonicalText":"董仲舒夢蛟龍入懷，乃作《春秋繁露》詞。其思深旨遠，天人感應之學，由此大備。","sentenceIds":["xijing-zaji_ch-2_p-14_s-1","xijing-zaji_ch-2_p-14_s-2"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/xijing-zaji/zh"},{"label":"維基文庫《西京雜記》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E8%A5%BF%E4%BA%AC%E9%9B%9C%E8%A8%98"}],"readingAid":{"translation":"大儒董仲舒在潛心鑽研《春秋》經義之時，夜裡夢見一條威嚴神聖的蛟龍飛入自己的懷抱之中，醒來後文思泉湧，於是創作了傳世名著《春秋繁露》的宏篇詞章！其思想深邃無比、立意宏遠廣博，漢代儒家以天人感應為核心的哲學體系，自此全面完備確立！","analysis":"【題解與董仲舒夢蛟龍入懷作春秋繁露】記載漢代新儒學宗師董仲舒創立「天人感應」與《春秋繁露》神聖經學體系之傳奇。\\n【詞義訓詁】「董仲舒」：西漢大儒，推動罷黜百家獨尊儒術；「春秋繁露」：董仲舒闡發春秋微言大義之哲學代表作；「蛟龍入懷」：象徵聖德與文思天啟。\\n【天人感應的儒學建構】董仲舒將儒家倫理與陰陽五行、災異譴告融為一體，構建了以「天人感應」為核心的漢代大一統國家意識形態。"}},{"id":"xijing-zaji_ch-2_p-15","chapterId":"xijing-zaji_ch-2","order":15,"canonicalText":"或問揚雄為賦，雄曰：「讀千首賦，乃能為之。」夫積學深厚，辭章自工，非可強致也。","sentenceIds":["xijing-zaji_ch-2_p-15_s-1","xijing-zaji_ch-2_p-15_s-2"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/xijing-zaji/zh"},{"label":"維基文庫《西京雜記》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E8%A5%BF%E4%BA%AC%E9%9B%9C%E8%A8%98"}],"readingAid":{"translation":"有人向揚雄請教如何才能寫好辭賦，揚雄回答說：必須先讀過一千首辭賦，然後才能夠自己動手寫。可見，只有累積了深厚扎實的學問基礎，寫出來的文章辭藻自然就會精巧工整，這絕對不是可以靠勉強湊合或速成所能達到的。","analysis":"【訓詁與名物】「或」有人。「揚雄」西漢著名辭賦家，與司馬相如並稱「揚馬」。「為賦」創作辭賦。「工」精巧、工整、優美。「強致」勉強達到、強求速成。\\n【章法與結構】本段為一則簡短的文學理論筆記。前半段以「問答對話」的形式，直接引述揚雄關於寫作經驗的名言（讀千首賦，乃能為之）；後半段則是作者（或記錄者）對這句話的歸納與評論（夫積學深厚...非可強致也），點破了量變產生質變的文學規律。\\n【思想與義理】這段話是中國古典文學理論中探討「繼承與創作（讀與寫）」關係的最著名論述之一。漢賦以辭藻華麗、用字艱深、鋪陳誇張著稱，對作者的詞彙量與學識要求極高。揚雄作為漢賦大家，他一針見血地指出：任何文學的創新與精巧（辭章自工），都必須建立在極其龐大的閱讀量與前人經驗的吸收之上（讀千首賦）。它打破了「文學純靠天才與靈感」的迷思，強調了「積學深厚」才是文學創作無法投機取巧的唯一正道（非可強致）。這對後世文學教育產生了深遠的影響。"}},{"id":"xijing-zaji_ch-2_p-16","chapterId":"xijing-zaji_ch-2","order":16,"canonicalText":"匡衡字稚圭，勤學而無燭。鄰舍有燭而不逮，衡乃穿壁引其光，以書映光而讀之。邑人大姓文不識，家富多書，衡乃與其傭作而不求償。主人怪問衡，衡曰：「願得讀主人書。」主人感嘆，資給以書，遂成大儒。","sentenceIds":["xijing-zaji_ch-2_p-16_s-1","xijing-zaji_ch-2_p-16_s-2","xijing-zaji_ch-2_p-16_s-3","xijing-zaji_ch-2_p-16_s-4","xijing-zaji_ch-2_p-16_s-5"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/xijing-zaji/zh"},{"label":"維基文庫《西京雜記》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E8%A5%BF%E4%BA%AC%E9%9B%9C%E8%A8%98"}],"readingAid":{"translation":"西漢名臣匡衡字稚圭，年輕求學時家境赤貧極度勤奮好學，然而家中夜晚貧困買不起蠟燭點燈。隔壁鄰居家每晚點著蠟燭但光線照不到匡衡家，匡衡於是在兩家的牆壁上悄悄鑿穿了一個小孔，引導隔壁透過來的一線微光，把書本映照在微光之下通宵達旦苦讀（鑿壁偷光）！同縣有一位藏書極其豐富的富豪名叫文不識，匡衡便主動前往文家給他當長工做繁重的苦力勞役，卻堅決分文不取工錢報酬。主人深感奇怪驚異地詢問匡衡原因，匡衡誠懇地說道：我只希望能有機會讀遍主人家中所收藏的全部書籍！主人聽後大受感動讚嘆不已，慷慨把家中的全部藏書免費借給他閱讀資助他求學，匡衡最終刻苦攻讀成為一代名震天下的大儒！","analysis":"【題解與背景】\\n本段選自《西京雜記》〈第二〉第 46 節。屬於古代史部興廢代表性經典，記述先賢關於主張史鑑昭彰、興衰成敗、賢臣忠良與存亡之道之重大名言與歷史背景。\\n【詞義與名物】\\n1. 經典名句解讀：引述「匡衡字稚圭勤學而無燭鄰舍有燭而不逮衡乃穿壁引……」之思想精華與章法結構。\\n2. 訓詁與古漢語語法：本段重點解讀「匡」、「衡」、「字」、「稚」等關鍵字詞之古代漢語語意、通假字與名物制度範式。\\n【思想與史事脈絡】\\n深刻傳達《西京雜記》知行合一與經世致用之哲理觀念，記錄歷史風雲演變、治亂興衰經驗與傑出人物之言行風範，為後世立德、立言、立功提供極具學術價值之智慧資糧與歷史參照。"}},{"id":"xijing-zaji_ch-2_p-17","chapterId":"xijing-zaji_ch-2","order":17,"canonicalText":"長安有儒生曰惠莊，聞朱雲折五鹿充宗之角，乃嘆息曰：「栗犢反能爾邪！吾終恥溺死溝中。」遂裹糧從師，精研《春秋》，亦為名儒。","sentenceIds":["xijing-zaji_ch-2_p-17_s-1","xijing-zaji_ch-2_p-17_s-2","xijing-zaji_ch-2_p-17_s-3"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/xijing-zaji/zh"},{"label":"維基文庫《西京雜記》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E8%A5%BF%E4%BA%AC%E9%9B%9C%E8%A8%98"}],"readingAid":{"translation":"長安城有一位儒生名叫惠莊，在聽聞太學生朱雲在朝堂經學辯論中以雄辯大才一舉駁倒大儒五鹿充宗（折五鹿充宗之角）之後，深受巨大震撼感嘆道：連朱雲這個平日像農村牛犢一樣粗魯剛烈的人（栗犢），尚且能夠在經學論辯中建此奇功！我如果庸庸碌碌一生、最終如同淹死在陰溝中一樣毫無作為，那將是我一生的莫大恥辱！於是惠莊立刻收拾行囊包裹乾糧出門尋訪名師，廢寢忘食精研《春秋》經義，最終也苦學成為一代名震海內的名儒！","analysis":"【題解與背景】\\n本段選自《西京雜記》〈第二〉第 47 節。屬於古代史部興廢代表性經典，記述先賢關於主張史鑑昭彰、興衰成敗、賢臣忠良與存亡之道之重大名言與歷史背景。\\n【詞義與名物】\\n1. 經典名句解讀：引述「長安有儒生曰惠莊聞朱雲折五鹿充宗之角乃嘆息曰……」之思想精華與章法結構。\\n2. 訓詁與古漢語語法：本段重點解讀「長」、「安」、「有」、「儒」等關鍵字詞之古代漢語語意、通假字與名物制度範式。\\n【思想與史事脈絡】\\n深刻傳達《西京雜記》知行合一與經世致用之哲理觀念，記錄歷史風雲演變、治亂興衰經驗與傑出人物之言行風範，為後世立德、立言、立功提供極具學術價值之智慧資糧與歷史參照。"}},{"id":"xijing-zaji_ch-2_p-18","chapterId":"xijing-zaji_ch-2","order":18,"canonicalText":"武帝過李夫人，就取玉簪搔頭。自此後，宮人搔頭皆用玉，玉價倍貴焉。","sentenceIds":["xijing-zaji_ch-2_p-18_s-1","xijing-zaji_ch-2_p-18_s-2"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/xijing-zaji/zh"},{"label":"維基文庫《西京雜記》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E8%A5%BF%E4%BA%AC%E9%9B%9C%E8%A8%98"}],"readingAid":{"translation":"漢武帝前往李夫人宮中探望探視，隨手順勢取下李夫人頭上佩戴的白玉髮簪用來搔頭止癢。從此之後，宮廷中的各位嬪妃宮女紛紛爭相效仿，日常搔頭固定髮髻全部改用玉簪（搔頭皆用玉），長安市場上的玉石價格因此暴漲數倍翻倍昂貴！","analysis":"【題解與背景】\\n本段選自《西京雜記》〈第二〉第 48 節。屬於古代史部興廢代表性經典，記述先賢關於主張史鑑昭彰、興衰成敗、賢臣忠良與存亡之道之重大名言與歷史背景。\\n【詞義與名物】\\n1. 經典名句解讀：引述「武帝過李夫人就取玉簪搔頭自此後宮人搔頭皆用玉……」之思想精華與章法結構。\\n2. 訓詁與古漢語語法：本段重點解讀「武」、「帝」、「過」、「李」等關鍵字詞之古代漢語語意、通假字與名物制度範式。\\n【思想與史事脈絡】\\n深刻傳達《西京雜記》知行合一與經世致用之哲理觀念，記錄歷史風雲演變、治亂興衰經驗與傑出人物之言行風範，為後世立德、立言、立功提供極具學術價值之智慧資糧與歷史參照。"}},{"id":"xijing-zaji_ch-2_p-19","chapterId":"xijing-zaji_ch-2","order":19,"canonicalText":"杜陵杜夫子善弈棊，為天下第一人。或譏其費日，夫子曰：「精其理者，足以大裨聖教。」蓋圍棊之道，通於兵法政理也。","sentenceIds":["xijing-zaji_ch-2_p-19_s-1","xijing-zaji_ch-2_p-19_s-2","xijing-zaji_ch-2_p-19_s-3"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/xijing-zaji/zh"},{"label":"維基文庫《西京雜記》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E8%A5%BF%E4%BA%AC%E9%9B%9C%E8%A8%98"}],"readingAid":{"translation":"長安杜陵的大師杜夫子極其擅長下圍棋（善弈棊），被公認為天下第一棋聖高手。當時有人譏諷批評他下棋是在白白浪費光陰耗費時日（費日），杜夫子從容回答說：能夠真正參透精通圍棋博弈之中陰陽攻守至理的人，其智慧完全足以極大裨益輔佐聖明先王的王道教化！因為圍棋的大道，本質上與軍事兵法調度和國家治理政治智慧是完全同一貫通的啊！","analysis":"【題解與背景】\\n本段選自《西京雜記》〈第二〉第 49 節。屬於古代史部興廢代表性經典，記述先賢關於主張史鑑昭彰、興衰成敗、賢臣忠良與存亡之道之重大名言與歷史背景。\\n【詞義與名物】\\n1. 經典名句解讀：引述「杜陵杜夫子善弈棊為天下第一人或譏其費日夫子曰……」之思想精華與章法結構。\\n2. 訓詁與古漢語語法：本段重點解讀「杜」、「陵」、「杜」、「夫」等關鍵字詞之古代漢語語意、通假字與名物制度範式。\\n【思想與史事脈絡】\\n深刻傳達《西京雜記》知行合一與經世致用之哲理觀念，記錄歷史風雲演變、治亂興衰經驗與傑出人物之言行風範，為後世立德、立言、立功提供極具學術價值之智慧資糧與歷史參照。"}},{"id":"xijing-zaji_ch-2_p-20","chapterId":"xijing-zaji_ch-2","order":20,"canonicalText":"成帝好蹴踘，群臣以蹴踘為勞體，非至尊所宜。帝曰：「朕好之，可擇似而不勞者奏之。」家君作彈棊以獻，帝大悅，賜金百斤。","sentenceIds":["xijing-zaji_ch-2_p-20_s-1","xijing-zaji_ch-2_p-20_s-2","xijing-zaji_ch-2_p-20_s-3"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/xijing-zaji/zh"},{"label":"維基文庫《西京雜記》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E8%A5%BF%E4%BA%AC%E9%9B%9C%E8%A8%98"}],"readingAid":{"translation":"漢成帝非常喜歡踢足球（蹴踘）。群臣認為踢足球太過消耗體力，不是尊貴的皇帝應該從事的運動，便加以勸諫。成帝說：但我就是喜歡玩，你們可以挑選一種性質類似足球，但又不會太勞累的遊戲進獻上來。於是，我的父親發明瞭一種名為彈棊的室內遊戲進獻給皇帝。成帝玩了之後非常高興，賞賜了黃金一百斤。","analysis":"【訓詁與名物】「蹴踘」讀ㄘㄨˋ ㄐㄩˊ，中國古代的足球運動，最初用於軍事訓練。「勞體」過度消耗體力。「至尊」指皇帝。「似」指性質或玩法類似蹴踘，具有競技性。「家君」作者對自己父親的尊稱（此處指劉向或某位宮廷近臣）。「彈棊」古代的一種室內棋類遊戲，雙方用手指彈擊棋子以擊打對方的棋子，類似現代的彈珠或桌球。\\n【章法與結構】本段是一則關於古代遊戲發明史的趣味筆記。文章按照「起因─發展─結果」的敘事結構展開：起因是成帝好蹴踘而群臣反對；發展是成帝提出了一個折衷的需求（似而不勞者）；結果是作者的父親順應聖意，發明瞭「彈棊」並獲得重賞。情節生動，充滿了生活氣息。\\n【思想與義理】這段記載不僅記錄了中國古代體育與遊戲發展史上的一件趣事（彈棊的發明），也側面反映了西漢中後期宮廷生活的奢靡與政治生態。漢成帝作為一個不理朝政的昏君，對於娛樂遊戲表現出極大的熱情（重賞百金）。而朝臣們雖然敢於勸諫皇帝不要做「勞體」的劇烈運動，但骨子裡卻還是為了迎合皇帝的享樂需求，甚至專門發明瞭室內微縮版的競技遊戲（彈棊）。這種君臣之間在「娛樂」上的互動，折射出當時政治風氣的輕浮與墮落。"}},{"id":"xijing-zaji_ch-2_p-21","chapterId":"xijing-zaji_ch-2","order":21,"canonicalText":"元封二年，大寒，雪深五尺，野鳥獸皆死，牛馬皆踡蹜如蝟，三輔人民凍死者十有二三。武帝下詔賑恤，發太倉粟以救之。","sentenceIds":["xijing-zaji_ch-2_p-21_s-1","xijing-zaji_ch-2_p-21_s-2"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/xijing-zaji/zh"},{"label":"維基文庫《西京雜記》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E8%A5%BF%E4%BA%AC%E9%9B%9C%E8%A8%98"}],"readingAid":{"translation":"漢武帝元封二年冬季，關中遭遇罕見極端特大寒潮嚴寒，大雪積雪深達五尺之厚，荒野之中的飛鳥野獸全部被活活凍死，民間的耕牛戰馬皆凍得蜷縮縮成一團如同一隻隻刺蝟（踡蹜如蝟），長安三輔地區的百姓平民被凍死者高達十分之二三！漢武帝聞訊極度震驚悲痛，立刻下達罪己與賑濟詔書，全面打開國家皇家太倉糧庫開倉放糧發放救濟物資，全力搶救受災百姓！","analysis":"【題解與背景】\\n本段選自《西京雜記》〈第二〉第 51 節。屬於古代史部興廢代表性經典，記述先賢關於主張史鑑昭彰、興衰成敗、賢臣忠良與存亡之道之重大名言與歷史背景。\\n【詞義與名物】\\n1. 經典名句解讀：引述「元封二年大寒雪深五尺野鳥獸皆死牛馬皆踡蹜如蝟……」之思想精華與章法結構。\\n2. 訓詁與古漢語語法：本段重點解讀「元」、「封」、「二」、「年」等關鍵字詞之古代漢語語意、通假字與名物制度範式。\\n【思想與史事脈絡】\\n深刻傳達《西京雜記》知行合一與經世致用之哲理觀念，記錄歷史風雲演變、治亂興衰經驗與傑出人物之言行風範，為後世立德、立言、立功提供極具學術價值之智慧資糧與歷史參照。"}},{"id":"xijing-zaji_ch-2_p-22","chapterId":"xijing-zaji_ch-2","order":22,"canonicalText":"武帝為七寶牀，雜寶桉，廁寶屏風，列寶帳，設於桂宮，時人謂之四寶宮。皆以夜光珠、珊瑚、琉璃為之。","sentenceIds":["xijing-zaji_ch-2_p-22_s-1","xijing-zaji_ch-2_p-22_s-2"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/xijing-zaji/zh"},{"label":"維基文庫《西京雜記》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E8%A5%BF%E4%BA%AC%E9%9B%9C%E8%A8%98"}],"readingAid":{"translation":"漢武帝耗資無數打造了七寶牀、雜寶案、廁寶屏風與列寶帳，整套奢華陳列安放在未央宮桂宮之中，當時的京城世人將這座宮殿稱之為四寶宮。這四套寶物全部採用罕見的夜光珍珠、深海紅珊瑚與五彩琉璃純工打造成！","analysis":"【題解與漢武帝桂宮四寶宮七寶牀雜寶案】描寫漢武帝桂宮內部集七寶牀、雜寶案、廁寶屏風、列寶帳於一體之頂級宮廷陳設工藝。\\n【詞義訓詁】「桂宮」：漢代未央宮北側離宮；「四寶宮」：以七寶牀、雜寶案、廁寶屏風、列寶帳著稱之奢華寢殿；「夜光珠」：古代發光珍珠。\\n【漢武帝時代的宮廷物質文明】漢武帝開拓西域四夷後，外國珍寶大量湧入長安，推動了皇家宮殿建築與室內工藝陳設達到前未有的繁複高峯。"}},{"id":"xijing-zaji_ch-2_p-23","chapterId":"xijing-zaji_ch-2","order":23,"canonicalText":"瓠子河決，有蛟龍從九子自決中逆上入河，噴沫流波數十里。武帝親臨決所，沈白馬玉璧以祭之，乃築宮其上，號曰宣房。","sentenceIds":["xijing-zaji_ch-2_p-23_s-1","xijing-zaji_ch-2_p-23_s-2"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/xijing-zaji/zh"},{"label":"維基文庫《西京雜記》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E8%A5%BF%E4%BA%AC%E9%9B%9C%E8%A8%98"}],"readingAid":{"translation":"黃河在瓠子口發生特大決口決堤（瓠子河決），洪水滔天之際，相傳有一條巨大蛟龍率領著九條龍子從決口洪水中逆流而上游入黃河，噴吐浪沫激起數十里的滔天巨浪！漢武帝親臨瓠子決口第一線指揮抗洪搶險，親自沉入白馬與名貴玉璧向河神祭祀，隨後發動數萬軍民合龍堵口，在決口故道之上修建宮殿紀念，命名為宣房宮！","analysis":"【題解與背景】\\n本段選自《西京雜記》〈第二〉第 53 節。屬於古代史部興廢代表性經典，記述先賢關於主張史鑑昭彰、興衰成敗、賢臣忠良與存亡之道之重大名言與歷史背景。\\n【詞義與名物】\\n1. 經典名句解讀：引述「瓠子河決有蛟龍從九子自決中逆上入河噴沫流波數……」之思想精華與章法結構。\\n2. 訓詁與古漢語語法：本段重點解讀「瓠」、「子」、「河」、「決」等關鍵字詞之古代漢語語意、通假字與名物制度範式。\\n【思想與史事脈絡】\\n深刻傳達《西京雜記》知行合一與經世致用之哲理觀念，記錄歷史風雲演變、治亂興衰經驗與傑出人物之言行風範，為後世立德、立言、立功提供極具學術價值之智慧資糧與歷史參照。"}},{"id":"xijing-zaji_ch-2_p-24","chapterId":"xijing-zaji_ch-2","order":24,"canonicalText":"文帝初，多雨，積霖至百日而止。京師米貴，斛至萬錢。文帝減膳節用，開倉賑給，天下乃安。","sentenceIds":["xijing-zaji_ch-2_p-24_s-1","xijing-zaji_ch-2_p-24_s-2","xijing-zaji_ch-2_p-24_s-3"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/xijing-zaji/zh"},{"label":"維基文庫《西京雜記》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E8%A5%BF%E4%BA%AC%E9%9B%9C%E8%A8%98"}],"readingAid":{"translation":"漢文帝即位初年，關中氣候極度異常連綿陰雨不斷，連續暴雨積霖整整下了一百天方纔停止！京師長安糧食短缺物價暴漲，一斛米價格竟然暴漲至一萬錢之巨！漢文帝身先士卒主動削減自己的御膳伙食、厲行節約節制宮廷開支，下令全面打開國家糧倉平價出售與免費發放糧食賑濟萬民，天下人心與社會秩序這才重新安定下來！","analysis":"【題解與文帝初年百日連陰雨減膳賑民】記錄漢文帝應對百日連陰雨極端氣候引發米價暴漲時「減膳節用、開倉賑給」之仁政風範。\\n【詞義訓詁】「積霖」：連綿不斷的大雨淫雨；「斛至萬錢」：米價飛漲反映極端糧食危機；「減膳節用」：皇帝主動削減御膳伙食以示自省悔過。\\n【古代天災應對與民本政治】面對重大自然災害，最高統治者主動節制宮廷消費、開倉賑濟災民，成為後世王朝應對水旱災荒的標準政治典範。"}},{"id":"xijing-zaji_ch-2_p-25","chapterId":"xijing-zaji_ch-2","order":25,"canonicalText":"王鳳以五月五日生，其父欲不舉，曰：「俗諺：『舉五日子，長及戶則自害，不則害其父母。』」其叔父曰：「昔孟嘗君亦五月五日生，卒相齊。何害之有！」乃舉之，後果大貴，為大將軍。","sentenceIds":["xijing-zaji_ch-2_p-25_s-1","xijing-zaji_ch-2_p-25_s-2","xijing-zaji_ch-2_p-25_s-3","xijing-zaji_ch-2_p-25_s-4"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/xijing-zaji/zh"},{"label":"維基文庫《西京雜記》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E8%A5%BF%E4%BA%AC%E9%9B%9C%E8%A8%98"}],"readingAid":{"translation":"西漢權臣王鳳恰好在農曆五月初五端午之日出生，他的父親王禁迷信民間惡俗想要遺棄不撫養他（欲不舉），說道：民間俗諺流傳：撫養五月五日出生的孩子，長大長到與門戶一樣高之際要麼自殘自殺，要麼就會剋死危害自己的父母！王鳳的叔父果斷站出來勸阻道：當年戰國四公子之一的孟嘗君田文也是在五月五日出生的，長大後最終官拜齊國正卿相國光宗耀祖！哪裡會有什麼危害呢！於是父親纔打消念頭撫養了他，王鳳長大後果然位極人臣大富大貴，官拜漢成帝大將軍執掌天下大權！","analysis":"【題解與背景】\\n本段選自《西京雜記》〈第二〉第 55 節。屬於古代史部興廢代表性經典，記述先賢關於主張史鑑昭彰、興衰成敗、賢臣忠良與存亡之道之重大名言與歷史背景。\\n【詞義與名物】\\n1. 經典名句解讀：引述「王鳳以五月五日生其父欲不舉曰俗諺舉五日子長及……」之思想精華與章法結構。\\n2. 訓詁與古漢語語法：本段重點解讀「王」、「鳳」、「五」、「月」等關鍵字詞之古代漢語語意、通假字與名物制度範式。\\n【思想與史事脈絡】\\n深刻傳達《西京雜記》知行合一與經世致用之哲理觀念，記錄歷史風雲演變、治亂興衰經驗與傑出人物之言行風範，為後世立德、立言、立功提供極具學術價值之智慧資糧與歷史參照。"}},{"id":"xijing-zaji_ch-2_p-26","chapterId":"xijing-zaji_ch-2","order":26,"canonicalText":"惠帝七年夏，雷震南山。大木數千株，皆火燃至末。其下數十畝地，草皆燋黃。其後百許日，家人就其處得化玉，大如指，色如碧，可以闢兵。","sentenceIds":["xijing-zaji_ch-2_p-26_s-1","xijing-zaji_ch-2_p-26_s-2","xijing-zaji_ch-2_p-26_s-3","xijing-zaji_ch-2_p-26_s-4"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/xijing-zaji/zh"},{"label":"維基文庫《西京雜記》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E8%A5%BF%E4%BA%AC%E9%9B%9C%E8%A8%98"}],"readingAid":{"translation":"漢惠帝七年夏天，雷暴閃電猛烈轟擊終南山。數千株參天大樹全部被天火雷擊引燃一直燒到樹梢末梢！雷火波及的下方數十畝山林土地，野草灌木全部被燒焦枯黃。在這場大火過去一百多天之後，當地山民前往火燒現場採集搜索，竟然在灰燼之中發現了高溫雷擊淬煉而成的奇異化玉，大小如同手指一般，顏色呈現深邃清澈的碧綠色，相傳隨身佩戴可以躲避兵刃刀劍傷害（闢兵）！","analysis":"【題解與惠帝七年雷震南山大火得闢兵化玉】記錄漢代終南山森林大火與雷電高溫熔融礦物形成「闢兵化玉（雷公墨/天然玻璃石）」之自然現象。\\n【詞義訓詁】「雷震南山」：雷電引發之秦嶺森林大火；「化玉」：高溫雷擊淬煉形成之熔融礦物；「闢兵」：闢通避，古代避除兵刃傷害之迷信信仰。\\n【漢代自然觀察與辟邪風俗】漢人將奇特的雷擊熔融礦物視為具有神異防護力量的靈物，生動反映了當時人們對自然奧祕的探索與樸素崇拜。"}},{"id":"xijing-zaji_ch-2_p-27","chapterId":"xijing-zaji_ch-2","order":27,"canonicalText":"高祖為泗水亭長，送徒驪山，將與故人訣去。徒卒贈高祖酒二壼，鹿肚、牛肝各一。高祖與樂從者飲酒於豐西澤中，夜斬白蛇，遂起義兵。","sentenceIds":["xijing-zaji_ch-2_p-27_s-1","xijing-zaji_ch-2_p-27_s-2","xijing-zaji_ch-2_p-27_s-3"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/xijing-zaji/zh"},{"label":"維基文庫《西京雜記》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E8%A5%BF%E4%BA%AC%E9%9B%9C%E8%A8%98"}],"readingAid":{"translation":"漢高祖劉邦當年擔任泗水亭長的時候，負責押送服役的民夫前往驪山，由於途中逃亡者眾多，他決定放走所有人，並準備與老朋友們訣別離去。那些被放走的役夫們湊錢贈送給高祖兩壺酒，以及鹿肚、牛肝各一份。高祖帶著那些願意跟隨他的人，在豐邑西邊的沼澤地裡喝酒壯膽。到了夜晚，他趁著酒意拔劍斬殺了一條擋路的白蛇，於是便就此起兵反秦了。","analysis":"【訓詁與名物】「泗水亭長」秦代基層官吏，主管當地治安。「徒」被徵發去服勞役的人。「驪山」秦始皇修建陵墓的地方。「訣去」訣別、離去（準備逃亡）。「徒卒」此指被押送的役夫。「樂從者」願意跟隨劉邦一起逃亡或起事的人。「斬白蛇」《史記》記載的劉邦起義神話，稱劉邦斬殺的白蛇是白帝之子，而劉邦是赤帝之子。\\n【章法與結構】本段以極其簡練的筆法，重述了漢高祖劉邦起義前夕的傳奇經歷。前一句交代了事件的背景與危機（送徒驪山，將訣去）；中間插入了一個正史未載的、極具市井生活氣息的微小細節（徒卒贈酒肉）；最後兩句則迅速拉昇了歷史的維度，將「飲酒豐澤」與「夜斬白蛇」這一開國神話相連接，最終落在「遂起義兵」的宏大歷史轉折上。\\n【思想與義理】《西京雜記》對「高祖斬白蛇」這一正史中充滿神學色彩的開國神話，進行了非常「世俗化」與「人情味」的細節補充。正史強調的是「赤帝子斬白帝子」的天命所歸；而這段記載卻特意記錄了役夫們贈送「酒二壼，鹿肚、牛肝」這樣粗鄙卻充滿江湖義氣的底層食物。這種視角的轉換，不僅讓劉邦這個流氓皇帝的形象更加立體與接地氣，也暗示了劉邦之所以能夠得天下，除了所謂的神話背書外，更重要的是他那種能夠在底層社會中收攏人心、與兄弟們大口喝酒喫肉的草莽江湖領袖氣質。"}},{"id":"xijing-zaji_ch-2_p-28","chapterId":"xijing-zaji_ch-2","order":28,"canonicalText":"梁孝王好營宮室苑囿之樂，作曜華之宮，築兔園。園中有百靈山，山有膚寸石、落猿巖、棲龍岫；又有雁池，池中有鶴洲、鳧渚。天下名士鄒陽、枚乘、司馬相如皆遊其間，極一時之盛。","sentenceIds":["xijing-zaji_ch-2_p-28_s-1","xijing-zaji_ch-2_p-28_s-2","xijing-zaji_ch-2_p-28_s-3","xijing-zaji_ch-2_p-28_s-4"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/xijing-zaji/zh"},{"label":"維基文庫《西京雜記》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E8%A5%BF%E4%BA%AC%E9%9B%9C%E8%A8%98"}],"readingAid":{"translation":"梁孝王劉武生平熱衷於營造宮殿園林遊賞之樂，在封國大興土木修建了富麗堂皇的曜華宮，修築了名震天下的梁園（兔園）。兔園之中堆疊修築了著名的百靈山，山中有形狀奇巧的膚寸石、險峻陡峭的落猿巖、雲霧繚繞的棲龍岫；園中又開鑿了浩瀚的雁池，池中散佈著仙鶴棲息的鶴洲與野鴨嬉戲的鳧渚。全天下的第一流辭賦名士如鄒陽、枚乘、司馬相如等人，無不匯聚在梁園之中遊賞賦詩，極盡漢代文人雅集盛極一時之盛況！","analysis":"【題解與背景】\\n本段選自《西京雜記》〈第二〉第 58 節。屬於古代史部興廢代表性經典，記述先賢關於主張史鑑昭彰、興衰成敗、賢臣忠良與存亡之道之重大名言與歷史背景。\\n【詞義與名物】\\n1. 經典名句解讀：引述「梁孝王好營宮室苑囿之樂作曜華之宮築兔園園中有……」之思想精華與章法結構。\\n2. 訓詁與古漢語語法：本段重點解讀「梁」、「孝」、「王」、「好」等關鍵字詞之古代漢語語意、通假字與名物制度範式。\\n【思想與史事脈絡】\\n深刻傳達《西京雜記》知行合一與經世致用之哲理觀念，記錄歷史風雲演變、治亂興衰經驗與傑出人物之言行風範，為後世立德、立言、立功提供極具學術價值之智慧資糧與歷史參照。"}},{"id":"xijing-zaji_ch-2_p-29","chapterId":"xijing-zaji_ch-2","order":29,"canonicalText":"魯恭王好鬭雞鴨及鵝鴈，養孔雀、鵁鶄，俸穀一年費二千石。又壞孔子舊宅以廣其宮，聞金石絲竹之聲，乃不敢壞。","sentenceIds":["xijing-zaji_ch-2_p-29_s-1","xijing-zaji_ch-2_p-29_s-2"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/xijing-zaji/zh"},{"label":"維基文庫《西京雜記》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E8%A5%BF%E4%BA%AC%E9%9B%9C%E8%A8%98"}],"readingAid":{"translation":"魯恭王劉餘生平極度喜愛鬥雞、鬥鴨以及觀賞鵝雁等禽鳥，在王府中大肆飼養珍禽孔雀與青頭鵁鶄，僅僅每年飼養禽鳥所消耗的王府俸祿穀物就多達兩千石之巨！後來他為了擴建自己的王宮大殿，竟然野蠻下令強拆孔子的曲阜舊宅（壞孔子宅）；在拆遷工人剛剛砸毀牆壁之際，忽然從牆壁廢墟之中傳來了神聖威嚴的鐘磬琴瑟金石絲竹仙樂之聲，魯恭王嚇得心驚膽戰，這才慌忙下令停工不敢再繼續拆毀！","analysis":"【題解與背景】\\n本段選自《西京雜記》〈第二〉第 59 節。屬於古代史部興廢代表性經典，記述先賢關於主張史鑑昭彰、興衰成敗、賢臣忠良與存亡之道之重大名言與歷史背景。\\n【詞義與名物】\\n1. 經典名句解讀：引述「魯恭王好鬭雞鴨及鵝鴈養孔雀鵁鶄俸穀一年費二千……」之思想精華與章法結構。\\n2. 訓詁與古漢語語法：本段重點解讀「魯」、「恭」、「王」、「好」等關鍵字詞之古代漢語語意、通假字與名物制度範式。\\n【思想與史事脈絡】\\n深刻傳達《西京雜記》知行合一與經世致用之哲理觀念，記錄歷史風雲演變、治亂興衰經驗與傑出人物之言行風範，為後世立德、立言、立功提供極具學術價值之智慧資糧與歷史參照。"}},{"id":"xijing-zaji_ch-2_p-30","chapterId":"xijing-zaji_ch-2","order":30,"canonicalText":"會稽歲時獻竹簟供御，世號為流黃簟。簟色如黃金，而滑澤如冰，夏月寢之，清涼徹骨。","sentenceIds":["xijing-zaji_ch-2_p-30_s-1","xijing-zaji_ch-2_p-30_s-2"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/xijing-zaji/zh"},{"label":"維基文庫《西京雜記》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E8%A5%BF%E4%BA%AC%E9%9B%9C%E8%A8%98"}],"readingAid":{"translation":"會稽郡每年按時節都會進獻一種精美的竹蓆供皇帝御用，世人稱之為流黃簟。這種竹蓆的顏色呈現出如黃金般的光澤，而且表面光滑得就像冰一樣。在炎熱的夏天睡在這種竹蓆上，會感到有一股清涼的感覺直透骨髓。","analysis":"【訓詁與名物】「會稽」漢代郡名，位於今浙江紹興一帶，盛產竹子。「歲時」每年按季節、時令。「供御」供給皇帝使用。「流黃簟」一種高級的竹蓆，因其色澤如流動的黃金而得名。「滑澤」光滑潤澤。「徹骨」透入骨髓，形容極度清涼。\\n【章法與結構】本段是一則典型的名產風物誌。首句交代了物品的產地（會稽）、身價（供御）與名稱（流黃簟）；第二句從視覺與觸覺兩個維度（色如黃金、滑澤如冰），極力描寫這種竹蓆精美的物理特徵；最後一句則點出其實用價值（夏月寢之，清涼徹骨），給人以極強的感官體驗。\\n【思想與義理】這段記載生動地展現了漢代江南地區（會稽）高超的竹編工藝水平，以及長安宮廷對地方名優特產的搜羅與享受。「流黃簟」這個充滿詩意與富貴氣息的名字，結合了「色如黃金」與「滑澤如冰」的感官描寫，將一件原本普通的夏日寢具，昇華為一件集實用性與審美性於一身的藝術珍品。這也從一個側面反映了西漢盛世時期，物資交流的繁榮以及統治階層在日常生活起居上追求極致精緻與奢華的時代風貌。"}},{"id":"xijing-zaji_ch-2_p-31","chapterId":"xijing-zaji_ch-2","order":31,"canonicalText":"朱買臣為會稽太守，懷章綬還至舍亭，而國人未知也。所知錢勃，見其暴露，乃勞之曰：「得無罷乎？」買臣引勃入亭，飲之酒，出章綬示之，勃大驚，馳走告郡中，郡中震動，皆郊迎拜伏。買臣之妻見之，慚恨自經。","sentenceIds":["xijing-zaji_ch-2_p-31_s-1","xijing-zaji_ch-2_p-31_s-2","xijing-zaji_ch-2_p-31_s-3","xijing-zaji_ch-2_p-31_s-4"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/xijing-zaji/zh"},{"label":"維基文庫《西京雜記》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E8%A5%BF%E4%BA%AC%E9%9B%9C%E8%A8%98"}],"readingAid":{"translation":"名士朱買臣被漢武帝破格任命為會稽郡太守，他身穿破舊衣服將象徵太守最高權力的金印紫綬悄悄藏在懷中（懷章綬）步行返回故鄉抵達舍亭驛站，而會稽全郡百姓官員尚且絲毫不知新太守已然微服抵達。朱買臣的老相識錢勃看見他風塵僕僕衣衫襤褸暴露在烈日下，便上前同情地慰問他說：老朋友這一路長途奔波，該不會累壞了吧？朱買臣親切引導錢勃走進驛亭，請他痛飲美酒，隨後從懷中掏出金印紫綬展示給錢勃看！錢勃定睛一看大驚失色魂飛魄散，立刻飛奔疾馳跑進郡城向官署官員大聲通報；會稽全城官民大為震動驚慌，全體官吏迅速奔赴城郊跪拜俯伏迎接新太守！當年嫌貧愛富拋棄朱買臣另嫁他人的前妻在人羣中目睹這一切，羞愧懊悔得無地自容，當天便自縊懸樑自盡身亡！","analysis":"【題解與朱買臣懷章綬還會稽前妻慚恨自經】本段為中國古代文人逆襲與戲曲故事最經典之傳奇母體——朱買臣「馬前潑水、衣錦還鄉、懷章綬歸會稽」之全本掌故！\\n【詞義訓詁】「朱買臣」：西漢著名窮儒，早年砍柴讀書，五十歲拜會稽太守；「懷章綬」：懷揣太守印信微服還鄉；「自經」：上吊自盡。\\n【世態炎涼之歷史寓言】生動刻畫了世俗社會對貧寒之士的白眼與對權力財富的盲從拜金，極具戲劇張力與深刻的社會批判價值。"}}],"sentences":[{"id":"xijing-zaji_ch-1_p-2_s-1","passageId":"xijing-zaji_ch-1_p-2","order":1,"canonicalText":"武帝作昆明池，欲伐昆吾夷，教習水戰。","chunks":[["武帝作昆明池，欲伐昆吾夷，教習水戰。","zh-Hant"]]},{"id":"xijing-zaji_ch-1_p-2_s-2","passageId":"xijing-zaji_ch-1_p-2","order":2,"canonicalText":"因而於上游戲養魚，魚給諸陵廟祭祀，餘付長安巿賣之。","chunks":[["因而於上游戲養魚，魚給諸陵廟祭祀，餘付長安巿賣之。","zh-Hant"]]},{"id":"xijing-zaji_ch-1_p-2_s-3","passageId":"xijing-zaji_ch-1_p-2","order":3,"canonicalText":"池周迴四十里，中作石鯨，長三丈，每至雷雨，往往鳴吼，鬣尾皆動。","chunks":[["池周迴四十里。","zh-Hant"]]},{"id":"xijing-zaji_ch-1_p-5_s-1","passageId":"xijing-zaji_ch-1_p-5","order":1,"canonicalText":"天子筆管，以錯寶為跗，毛皆以秋兔之毫，官師路扈為之。","chunks":[["天子筆管，以錯寶為跗，毛皆以秋兔之毫，官師路扈為之。","zh-Hant"]]},{"id":"xijing-zaji_ch-1_p-5_s-2","passageId":"xijing-zaji_ch-1_p-5","order":2,"canonicalText":"以雜寶為匣，廁以玉璧翠羽，皆直百金。","chunks":[["以雜寶為匣，廁以玉璧翠羽，皆直百金。","zh-Hant"]]},{"id":"xijing-zaji_ch-1_p-9_s-1","passageId":"xijing-zaji_ch-1_p-9","order":1,"canonicalText":"戚姬以百鍊金為彄環，照見指骨。","chunks":[["戚姬以百鍊金為彄環，照見指骨。","zh-Hant"]]},{"id":"xijing-zaji_ch-1_p-9_s-2","passageId":"xijing-zaji_ch-1_p-9","order":2,"canonicalText":"上惡之，以賜侍兒鳴玉、耀光等，各四枚。","chunks":[["上惡之，以賜侍兒鳴玉、耀光等，各四枚。","zh-Hant"]]},{"id":"xijing-zaji_ch-1_p-10_s-1","passageId":"xijing-zaji_ch-1_p-10","order":1,"canonicalText":"趙王如意年幼，未能親外傅。","chunks":[["趙王如意年幼，未能親外傅。","zh-Hant"]]},{"id":"xijing-zaji_ch-1_p-10_s-2","passageId":"xijing-zaji_ch-1_p-10","order":2,"canonicalText":"戚姬使舊趙王內傅趙媼傅之，號其室曰養德宮，後改為魚藻宮。","chunks":[["戚姬使舊趙王內傅趙媼傅之，號其室曰養德宮，後改為魚藻宮。","zh-Hant"]]},{"id":"xijing-zaji_ch-1_p-13_s-1","passageId":"xijing-zaji_ch-1_p-13","order":1,"canonicalText":"終南山多離合草，葉似江蘺，而紅綠相雜，莖皆紫色，氣如蘿勒。","chunks":[["終南山多離合草，葉似江蘺，而紅綠相雜，莖皆紫色，氣如蘿勒。","zh-Hant"]]},{"id":"xijing-zaji_ch-1_p-13_s-2","passageId":"xijing-zaji_ch-1_p-13","order":2,"canonicalText":"有樹直上百丈，無枝，上結叢條如車蓋，名曰影樹。","chunks":[["有樹直上百丈，無枝，上結叢條如車蓋，葉一青一赤，望之班駮如錦繡，長安謂之丹青樹，亦云華蓋樹。","zh-Hant"]]},{"id":"xijing-zaji_ch-1_p-13_s-3","passageId":"xijing-zaji_ch-1_p-13","order":3,"canonicalText":"日中則影生，日落則影滅。","chunks":[["亦生熊耳山。","zh-Hant"]]},{"id":"xijing-zaji_ch-1_p-19_s-1","passageId":"xijing-zaji_ch-1_p-19","order":1,"canonicalText":"五鹿充宗受學於弘成子。","chunks":[["五鹿充宗受學於弘成子。","zh-Hant"]]},{"id":"xijing-zaji_ch-1_p-19_s-2","passageId":"xijing-zaji_ch-1_p-19","order":2,"canonicalText":"成子少時，嘗有人過己，授以文石，大如鷰卵。","chunks":[["成子少時，嘗有人過己，授以文石，大如鷰卵。","zh-Hant"]]},{"id":"xijing-zaji_ch-1_p-19_s-3","passageId":"xijing-zaji_ch-1_p-19","order":3,"canonicalText":"成子吞之，遂大明悟，為天下大儒。","chunks":[["成子吞之，遂大明悟，為天下通儒。","zh-Hant"]]},{"id":"xijing-zaji_ch-1_p-19_s-4","passageId":"xijing-zaji_ch-1_p-19","order":4,"canonicalText":"充宗得其傳，為梁丘《易》。","chunks":[["成子後病，吐出此石，以授充宗，充宗又為碩學也。","zh-Hant"]]},{"id":"xijing-zaji_ch-1_p-20_s-1","passageId":"xijing-zaji_ch-1_p-20","order":1,"canonicalText":"始元元年，黃鵠下太液池。","chunks":[["始元元年，黃鵠下太液池。","zh-Hant"]]},{"id":"xijing-zaji_ch-1_p-20_s-2","passageId":"xijing-zaji_ch-1_p-20","order":2,"canonicalText":"上為歌曰：「黃鵠飛兮下建章，羽肅肅兮行蹌蹌，金為衣兮菊為裳。","chunks":[["上為歌曰：「黃鵠飛兮下建章，羽肅肅兮行蹌蹌，金為衣兮菊為裳。","zh-Hant"]]},{"id":"xijing-zaji_ch-1_p-20_s-3","passageId":"xijing-zaji_ch-1_p-20","order":3,"canonicalText":"唼喋荷浪，息宴蘭房。","chunks":[["唼喋荷荇，出入蒹葭，自顧菲薄，愧爾嘉祥。","zh-Hant"]]},{"id":"xijing-zaji_ch-1_p-20_s-4","passageId":"xijing-zaji_ch-1_p-20","order":4,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"xijing-zaji_ch-1_p-25_s-1","passageId":"xijing-zaji_ch-1_p-25","order":1,"canonicalText":"積草池中有珊瑚樹，高一丈二尺，一本三柯，上有四百六十二條。","chunks":[["積草池中有珊瑚樹，高一丈二尺，一本三柯，上有四百六十二條。","zh-Hant"]]},{"id":"xijing-zaji_ch-1_p-25_s-2","passageId":"xijing-zaji_ch-1_p-25","order":2,"canonicalText":"是南越王趙他所獻，號為烽火樹。","chunks":[["是南越王趙他所獻，號為烽火樹。","zh-Hant"]]},{"id":"xijing-zaji_ch-1_p-25_s-3","passageId":"xijing-zaji_ch-1_p-25","order":3,"canonicalText":"至夜光景常明，如火之照。","chunks":[["至夜，光景常欲燃。","zh-Hant"]]},{"id":"xijing-zaji_ch-1_p-26_s-1","passageId":"xijing-zaji_ch-1_p-26","order":1,"canonicalText":"昆明池刻玉石為魚，每至雷雨，魚常鳴吼，鬐尾皆動。","chunks":[["昆明池刻玉石為魚，每至雷雨，魚常鳴吼，鬐尾皆動。","zh-Hant"]]},{"id":"xijing-zaji_ch-1_p-26_s-2","passageId":"xijing-zaji_ch-1_p-26","order":2,"canonicalText":"漢世祭之以祈雨，往往有驗。","chunks":[["漢世祭之以祈雨，往往有驗。","zh-Hant"]]},{"id":"xijing-zaji_ch-1_p-29_s-1","passageId":"xijing-zaji_ch-1_p-29","order":1,"canonicalText":"趙飛鷰為皇后，其女弟在昭陽殿，遺飛鷰書曰：「今日嘉辰，貴姊懋膺洪冊，謹上襚三十五條，以陳踴躍之懽。","chunks":[["趙飛鷰為皇后，其女弟在昭陽殿，遺飛鷰書曰：「今日嘉辰，貴姊懋膺洪冊，謹上襚三十五條，以陳踊躍之心：金華紫輪帽，金華紫羅面衣，織成上襦，織成下裳，五色文綬，鴛鴦襦，鴛鴦被，鴛鴦褥，金錯繡襠，七寶綦履，五色文玉環，同心七寶釵，黃金步搖，合懽圓璫，琥珀枕，龜文枕，珊瑚玦，馬腦彄，雲母扇，孔雀扇，翠羽扇，九華扇，五明扇，雲母屏風，琉璃屏風，五層金博山香鑪，迴風扇，椰葉席，同心梅，含枝李，青木香，瀋水香，香螺巵，九真雄麝香，七枝鐙。","zh-Hant"]]},{"id":"xijing-zaji_ch-1_p-29_s-2","passageId":"xijing-zaji_ch-1_p-29","order":2,"canonicalText":"」有金錯連環、文犀簟、沉香水、九華扇、綠玉燈、百寶屏風。","chunks":[["」","zh-Hant"]]},{"id":"xijing-zaji_ch-2_p-3_s-1","passageId":"xijing-zaji_ch-2_p-3","order":1,"canonicalText":"五侯不相能，賓客不得來往。","chunks":[["五侯不相能，賓客不得來往。","zh-Hant"]]},{"id":"xijing-zaji_ch-2_p-3_s-2","passageId":"xijing-zaji_ch-2_p-3","order":2,"canonicalText":"婁護豐辯，傳食五侯間，各得其懽心，競致奇膳。","chunks":[["婁護豐辯，傳食五侯間，各得其懽心，競致奇膳。","zh-Hant"]]},{"id":"xijing-zaji_ch-2_p-3_s-3","passageId":"xijing-zaji_ch-2_p-3","order":3,"canonicalText":"護乃合以為鯖，世稱五侯鯖。","chunks":[["護乃合以為鯖，世稱五侯鯖，以為奇味焉。","zh-Hant"]]},{"id":"xijing-zaji_ch-2_p-11_s-1","passageId":"xijing-zaji_ch-2_p-11","order":1,"canonicalText":"漢諸陵寢，皆以竹為簾，簾皆為水紋及龍鳳之像。","chunks":[["漢諸陵寢，皆以竹為簾，簾皆為水紋及龍鳳之像。","zh-Hant"]]},{"id":"xijing-zaji_ch-2_p-11_s-2","passageId":"xijing-zaji_ch-2_p-11","order":2,"canonicalText":"昭陽殿織珠為簾，風至則鳴，如珩珮之聲。","chunks":[["昭陽殿織珠為簾，風至則鳴，如珩珮之聲。","zh-Hant"]]},{"id":"xijing-zaji_ch-2_p-12_s-1","passageId":"xijing-zaji_ch-2_p-12","order":1,"canonicalText":"揚雄讀書，有人語之曰：「無為自苦，玄故難傳。","chunks":[["楊雄讀書，有人語之曰：「無為自苦，玄故難傳。","zh-Hant"]]},{"id":"xijing-zaji_ch-2_p-12_s-2","passageId":"xijing-zaji_ch-2_p-12","order":2,"canonicalText":"」忽然不見。","chunks":[["」忽然不見。","zh-Hant"]]},{"id":"xijing-zaji_ch-2_p-12_s-3","passageId":"xijing-zaji_ch-2_p-12","order":3,"canonicalText":"雄著《太玄經》，夢吐鳳凰，集《玄》書之上，雄乃續成之。","chunks":[["雄著《太玄經》，夢吐鳳凰，集《玄》之上，頃而滅。","zh-Hant"]]},{"id":"xijing-zaji_ch-2_p-15_s-1","passageId":"xijing-zaji_ch-2_p-15","order":1,"canonicalText":"或問揚雄為賦，雄曰：「讀千首賦，乃能為之。","chunks":[["或問楊雄為賦，雄曰：「讀千首賦，乃能為之。","zh-Hant"]]},{"id":"xijing-zaji_ch-2_p-15_s-2","passageId":"xijing-zaji_ch-2_p-15","order":2,"canonicalText":"」夫積學深厚，辭章自工，非可強致也。","chunks":[["」","zh-Hant"]]},{"id":"xijing-zaji_ch-2_p-18_s-1","passageId":"xijing-zaji_ch-2_p-18","order":1,"canonicalText":"武帝過李夫人，就取玉簪搔頭。","chunks":[["武帝過李夫人，就取玉簪搔頭。","zh-Hant"]]},{"id":"xijing-zaji_ch-2_p-18_s-2","passageId":"xijing-zaji_ch-2_p-18","order":2,"canonicalText":"自此後，宮人搔頭皆用玉，玉價倍貴焉。","chunks":[["自此後，宮人搔頭皆用玉，玉價倍貴焉。","zh-Hant"]]},{"id":"xijing-zaji_ch-2_p-19_s-1","passageId":"xijing-zaji_ch-2_p-19","order":1,"canonicalText":"杜陵杜夫子善弈棊，為天下第一人。","chunks":[["杜陵杜夫子善弈棊，為天下第一人。","zh-Hant"]]},{"id":"xijing-zaji_ch-2_p-19_s-2","passageId":"xijing-zaji_ch-2_p-19","order":2,"canonicalText":"或譏其費日，夫子曰：「精其理者，足以大裨聖教。","chunks":[["或譏其費日，夫子曰：「精其理者，足以大裨聖教。","zh-Hant"]]},{"id":"xijing-zaji_ch-2_p-19_s-3","passageId":"xijing-zaji_ch-2_p-19","order":3,"canonicalText":"」蓋圍棊之道，通於兵法政理也。","chunks":[["」","zh-Hant"]]},{"id":"xijing-zaji_ch-2_p-20_s-1","passageId":"xijing-zaji_ch-2_p-20","order":1,"canonicalText":"成帝好蹴踘，群臣以蹴踘為勞體，非至尊所宜。","chunks":[["成帝好蹴踘，群臣以蹴踘為勞體，非至尊所宜。","zh-Hant"]]},{"id":"xijing-zaji_ch-2_p-20_s-2","passageId":"xijing-zaji_ch-2_p-20","order":2,"canonicalText":"帝曰：「朕好之，可擇似而不勞者奏之。","chunks":[["帝曰：「朕好之，可擇似而不勞者奏之。","zh-Hant"]]},{"id":"xijing-zaji_ch-2_p-20_s-3","passageId":"xijing-zaji_ch-2_p-20","order":3,"canonicalText":"」家君作彈棊以獻，帝大悅，賜金百斤。","chunks":[["」家君作彈棊以獻，帝大悅，賜青羔裘、紫絲履，服以朝覲。","zh-Hant"]]},{"id":"xijing-zaji_ch-2_p-26_s-1","passageId":"xijing-zaji_ch-2_p-26","order":1,"canonicalText":"惠帝七年夏，雷震南山。","chunks":[["惠帝七年夏，雷震南山。","zh-Hant"]]},{"id":"xijing-zaji_ch-2_p-26_s-2","passageId":"xijing-zaji_ch-2_p-26","order":2,"canonicalText":"大木數千株，皆火燃至末。","chunks":[["大木數千株，皆火燃至末。","zh-Hant"]]},{"id":"xijing-zaji_ch-2_p-26_s-3","passageId":"xijing-zaji_ch-2_p-26","order":3,"canonicalText":"其下數十畝地，草皆燋黃。","chunks":[["其下數十畝地，草皆燋黃。","zh-Hant"]]},{"id":"xijing-zaji_ch-2_p-26_s-4","passageId":"xijing-zaji_ch-2_p-26","order":4,"canonicalText":"其後百許日，家人就其處得化玉，大如指，色如碧，可以闢兵。","chunks":[["其後百許日，家人就其間得龍骨一具，鮫骨二具。","zh-Hant"]]},{"id":"xijing-zaji_ch-2_p-31_s-1","passageId":"xijing-zaji_ch-2_p-31","order":1,"canonicalText":"朱買臣為會稽太守，懷章綬還至舍亭，而國人未知也。","chunks":[["朱買臣為會稽太守，懷章綬還至舍亭，而國人未知也。","zh-Hant"]]},{"id":"xijing-zaji_ch-2_p-31_s-2","passageId":"xijing-zaji_ch-2_p-31","order":2,"canonicalText":"所知錢勃，見其暴露，乃勞之曰：「得無罷乎？","chunks":[["所知錢勃，見其暴露，乃勞之曰：「得無罷乎？","zh-Hant"]]},{"id":"xijing-zaji_ch-2_p-31_s-3","passageId":"xijing-zaji_ch-2_p-31","order":3,"canonicalText":"」買臣引勃入亭，飲之酒，出章綬示之，勃大驚，馳走告郡中，郡中震動，皆郊迎拜伏。","chunks":[["」遺與紈扇。","zh-Hant"]]},{"id":"xijing-zaji_ch-2_p-31_s-4","passageId":"xijing-zaji_ch-2_p-31","order":4,"canonicalText":"買臣之妻見之，慚恨自經。","chunks":[["買臣至郡，引為上客，尋遷為掾史。","zh-Hant"]]},{"id":"xijing-zaji_ch-1_p-1_s-1","chapterId":"xijing-zaji_ch-1","passageId":"xijing-zaji_ch-1_p-1","order":1,"canonicalText":"漢高帝七年，蕭相國營未央宮。","chunks":[]},{"id":"xijing-zaji_ch-1_p-1_s-2","chapterId":"xijing-zaji_ch-1","passageId":"xijing-zaji_ch-1_p-1","order":2,"canonicalText":"因龍首山製前殿，建北闕。","chunks":[]},{"id":"xijing-zaji_ch-1_p-1_s-3","chapterId":"xijing-zaji_ch-1","passageId":"xijing-zaji_ch-1_p-1","order":3,"canonicalText":"未央宮周迴二十二里九十五步五尺，街道周迴七十里，臺閣殿觀三十有二。","chunks":[]},{"id":"xijing-zaji_ch-1_p-1_s-4","chapterId":"xijing-zaji_ch-1","passageId":"xijing-zaji_ch-1_p-1","order":4,"canonicalText":"西入武庫，東入太倉。","chunks":[]},{"id":"xijing-zaji_ch-1_p-1_s-5","chapterId":"xijing-zaji_ch-1","passageId":"xijing-zaji_ch-1_p-1","order":5,"canonicalText":"前殿東西五十丈，深十五丈，高三十五丈。","chunks":[]},{"id":"xijing-zaji_ch-1_p-3_s-1","chapterId":"xijing-zaji_ch-1","passageId":"xijing-zaji_ch-1_p-3","order":1,"canonicalText":"漢制：宗廟八月飲酎，用九醞太牢，皇帝侍祠。","chunks":[]},{"id":"xijing-zaji_ch-1_p-3_s-2","chapterId":"xijing-zaji_ch-1","passageId":"xijing-zaji_ch-1_p-3","order":2,"canonicalText":"以正月旦作酒，八月成，名曰酎，一曰九醞，一名醇酎。","chunks":[]},{"id":"xijing-zaji_ch-1_p-3_s-3","chapterId":"xijing-zaji_ch-1","passageId":"xijing-zaji_ch-1_p-3","order":3,"canonicalText":"諸侯各獻黃金以助祭，少者得罪，名曰酎金。","chunks":[]},{"id":"xijing-zaji_ch-1_p-4_s-1","chapterId":"xijing-zaji_ch-1","passageId":"xijing-zaji_ch-1_p-4","order":1,"canonicalText":"京師大水，祭山川以止雨。","chunks":[]},{"id":"xijing-zaji_ch-1_p-4_s-2","chapterId":"xijing-zaji_ch-1","passageId":"xijing-zaji_ch-1_p-4","order":2,"canonicalText":"丞相御史二千石禱祠，如求雨法。","chunks":[]},{"id":"xijing-zaji_ch-1_p-4_s-3","chapterId":"xijing-zaji_ch-1","passageId":"xijing-zaji_ch-1_p-4","order":3,"canonicalText":"設壇於城外，官吏素服，以祈天應。","chunks":[]},{"id":"xijing-zaji_ch-1_p-6_s-1","chapterId":"xijing-zaji_ch-1","passageId":"xijing-zaji_ch-1_p-6","order":1,"canonicalText":"漢制：天子玉幾，冬則加綈錦其上，謂之綈幾。","chunks":[]},{"id":"xijing-zaji_ch-1_p-6_s-2","chapterId":"xijing-zaji_ch-1","passageId":"xijing-zaji_ch-1_p-6","order":2,"canonicalText":"以象牙為火籠，籠上皆散華文，後宮則五色綾文。","chunks":[]},{"id":"xijing-zaji_ch-1_p-6_s-3","chapterId":"xijing-zaji_ch-1","passageId":"xijing-zaji_ch-1_p-6","order":3,"canonicalText":"以酒沃炭，則火光不耀而溫煖。","chunks":[]},{"id":"xijing-zaji_ch-1_p-7_s-1","chapterId":"xijing-zaji_ch-1","passageId":"xijing-zaji_ch-1_p-7","order":1,"canonicalText":"武帝時，西域獻吉光裘，入水不濡。","chunks":[]},{"id":"xijing-zaji_ch-1_p-7_s-2","chapterId":"xijing-zaji_ch-1","passageId":"xijing-zaji_ch-1_p-7","order":2,"canonicalText":"上時服此裘以聽朝。","chunks":[]},{"id":"xijing-zaji_ch-1_p-7_s-3","chapterId":"xijing-zaji_ch-1","passageId":"xijing-zaji_ch-1_p-7","order":3,"canonicalText":"吉光神馬，出大月氏，其毛毛黃皮柔，百年不腐。","chunks":[]},{"id":"xijing-zaji_ch-1_p-8_s-1","chapterId":"xijing-zaji_ch-1","passageId":"xijing-zaji_ch-1_p-8","order":1,"canonicalText":"高帝、戚夫人善鼓瑟擊築。","chunks":[]},{"id":"xijing-zaji_ch-1_p-8_s-2","chapterId":"xijing-zaji_ch-1","passageId":"xijing-zaji_ch-1_p-8","order":2,"canonicalText":"帝常擁夫人倚瑟而絃歌，畢，每泣下流漣。","chunks":[]},{"id":"xijing-zaji_ch-1_p-8_s-3","chapterId":"xijing-zaji_ch-1","passageId":"xijing-zaji_ch-1_p-8","order":3,"canonicalText":"夫人善為翹袖折腰之舞，歌《出塞》、《入塞》之曲。","chunks":[]},{"id":"xijing-zaji_ch-1_p-11_s-1","chapterId":"xijing-zaji_ch-1","passageId":"xijing-zaji_ch-1_p-11","order":1,"canonicalText":"惠帝嘗與趙王同寢處，呂後欲殺之而未得。","chunks":[]},{"id":"xijing-zaji_ch-1_p-11_s-2","chapterId":"xijing-zaji_ch-1","passageId":"xijing-zaji_ch-1_p-11","order":2,"canonicalText":"後帝早獵，王不能夙興，呂後命力士於被中縊殺之。","chunks":[]},{"id":"xijing-zaji_ch-1_p-11_s-3","chapterId":"xijing-zaji_ch-1","passageId":"xijing-zaji_ch-1_p-11","order":3,"canonicalText":"及死，呂後令斷戚夫人手足，號曰人彘。","chunks":[]},{"id":"xijing-zaji_ch-1_p-12_s-1","chapterId":"xijing-zaji_ch-1","passageId":"xijing-zaji_ch-1_p-12","order":1,"canonicalText":"樂遊苑自生玫瑰樹，樹下多苜蓿。","chunks":[]},{"id":"xijing-zaji_ch-1_p-12_s-2","chapterId":"xijing-zaji_ch-1","passageId":"xijing-zaji_ch-1_p-12","order":2,"canonicalText":"苜蓿一名懷風，時人或謂之光風，風在其間，常蕭蕭然，日照其花，有光彩，故名光風。","chunks":[]},{"id":"xijing-zaji_ch-1_p-12_s-3","chapterId":"xijing-zaji_ch-1","passageId":"xijing-zaji_ch-1_p-12","order":3,"canonicalText":"茂陵人謂之連枝草。","chunks":[]},{"id":"xijing-zaji_ch-1_p-14_s-1","chapterId":"xijing-zaji_ch-1","passageId":"xijing-zaji_ch-1_p-14","order":1,"canonicalText":"漢帝相傳以秦王子嬰所奉白玉璽、高祖斬白蛇劍。","chunks":[]},{"id":"xijing-zaji_ch-1_p-14_s-2","chapterId":"xijing-zaji_ch-1","passageId":"xijing-zaji_ch-1_p-14","order":2,"canonicalText":"劍上有七採珠、九華玉以為飾，雜廁五色琉璃為劍匣。","chunks":[]},{"id":"xijing-zaji_ch-1_p-14_s-3","chapterId":"xijing-zaji_ch-1","passageId":"xijing-zaji_ch-1_p-14","order":3,"canonicalText":"匣上題曰：提三尺以取天下。","chunks":[]},{"id":"xijing-zaji_ch-1_p-15_s-1","chapterId":"xijing-zaji_ch-1","passageId":"xijing-zaji_ch-1_p-15","order":1,"canonicalText":"漢綵女常以七月七日穿七孔鍼於開襟樓，俱以習之。","chunks":[]},{"id":"xijing-zaji_ch-1_p-15_s-2","chapterId":"xijing-zaji_ch-1","passageId":"xijing-zaji_ch-1_p-15","order":2,"canonicalText":"相傳是夕織女渡河，宮人鹹乞巧焉。","chunks":[]},{"id":"xijing-zaji_ch-1_p-16_s-1","chapterId":"xijing-zaji_ch-1","passageId":"xijing-zaji_ch-1_p-16","order":1,"canonicalText":"宣帝被收擊郡邸獄，臂上猶帶史良娣合採婉轉絲繩，擊身毒國寶鏡一枚，大如八銖錢。","chunks":[]},{"id":"xijing-zaji_ch-1_p-16_s-2","chapterId":"xijing-zaji_ch-1","passageId":"xijing-zaji_ch-1_p-16","order":2,"canonicalText":"舊傳此鏡見妖魅，持之可以照見五臟。","chunks":[]},{"id":"xijing-zaji_ch-1_p-17_s-1","chapterId":"xijing-zaji_ch-1","passageId":"xijing-zaji_ch-1_p-17","order":1,"canonicalText":"霍光妻遺淳于衍蒲桃錦二十四匹、散花綾二十五匹。","chunks":[]},{"id":"xijing-zaji_ch-1_p-17_s-2","chapterId":"xijing-zaji_ch-1","passageId":"xijing-zaji_ch-1_p-17","order":2,"canonicalText":"綾出鉅鹿陳寶光家，寶光妻傳其法。","chunks":[]},{"id":"xijing-zaji_ch-1_p-17_s-3","chapterId":"xijing-zaji_ch-1","passageId":"xijing-zaji_ch-1_p-17","order":3,"canonicalText":"霍顯召入其第，使作之。","chunks":[]},{"id":"xijing-zaji_ch-1_p-17_s-4","chapterId":"xijing-zaji_ch-1","passageId":"xijing-zaji_ch-1_p-17","order":4,"canonicalText":"機用百二十躡，六十日成一匹，匹值萬錢。","chunks":[]},{"id":"xijing-zaji_ch-1_p-18_s-1","chapterId":"xijing-zaji_ch-1","passageId":"xijing-zaji_ch-1_p-18","order":1,"canonicalText":"濟陰王興居反，始舉兵，大風從東來，直吹其旌旗，飛上天入雲，而墮城西井中。","chunks":[]},{"id":"xijing-zaji_ch-1_p-18_s-2","chapterId":"xijing-zaji_ch-1","passageId":"xijing-zaji_ch-1_p-18","order":2,"canonicalText":"馬皆悲鳴不進。","chunks":[]},{"id":"xijing-zaji_ch-1_p-18_s-3","chapterId":"xijing-zaji_ch-1","passageId":"xijing-zaji_ch-1_p-18","order":3,"canonicalText":"左右皆懼，後果兵敗自殺。","chunks":[]},{"id":"xijing-zaji_ch-1_p-21_s-1","chapterId":"xijing-zaji_ch-1","passageId":"xijing-zaji_ch-1_p-21","order":1,"canonicalText":"漢帝送死皆珠襦玉匣。","chunks":[]},{"id":"xijing-zaji_ch-1_p-21_s-2","chapterId":"xijing-zaji_ch-1","passageId":"xijing-zaji_ch-1_p-21","order":2,"canonicalText":"匣形如鎧甲，連以金縷。","chunks":[]},{"id":"xijing-zaji_ch-1_p-21_s-3","chapterId":"xijing-zaji_ch-1","passageId":"xijing-zaji_ch-1_p-21","order":3,"canonicalText":"武帝匣上皆鏤為蛟龍鸞鳳龜麟之象，世謂為蛟龍玉匣。","chunks":[]},{"id":"xijing-zaji_ch-1_p-21_s-4","chapterId":"xijing-zaji_ch-1","passageId":"xijing-zaji_ch-1_p-21","order":4,"canonicalText":"梓宮以文梓為棺，題湊其上。","chunks":[]},{"id":"xijing-zaji_ch-1_p-22_s-1","chapterId":"xijing-zaji_ch-1","passageId":"xijing-zaji_ch-1_p-22","order":1,"canonicalText":"成帝設雲帳、雲幄、雲幕於甘泉紫殿，世謂三雲殿。","chunks":[]},{"id":"xijing-zaji_ch-1_p-22_s-2","chapterId":"xijing-zaji_ch-1","passageId":"xijing-zaji_ch-1_p-22","order":2,"canonicalText":"皆以輕綃為之，風至則飄揚如雲氣。","chunks":[]},{"id":"xijing-zaji_ch-1_p-23_s-1","chapterId":"xijing-zaji_ch-1","passageId":"xijing-zaji_ch-1_p-23","order":1,"canonicalText":"漢掖庭有月影臺、雲光殿、九華殿、鳴鸞殿、開襟閣、臨池觀，不在簿籍，皆繁華窈窕之所棲宿焉。","chunks":[]},{"id":"xijing-zaji_ch-1_p-23_s-2","chapterId":"xijing-zaji_ch-1","passageId":"xijing-zaji_ch-1_p-23","order":2,"canonicalText":"宮女數千，各極妖妍。","chunks":[]},{"id":"xijing-zaji_ch-1_p-24_s-1","chapterId":"xijing-zaji_ch-1","passageId":"xijing-zaji_ch-1_p-24","order":1,"canonicalText":"趙飛鷰女弟居昭陽殿，中庭彤朱，而殿上丹漆，砌皆銅沓，黃金塗，白玉階，璧帶往往為黃金釭，含藍田璧，明珠翠羽飾之。","chunks":[]},{"id":"xijing-zaji_ch-1_p-27_s-1","chapterId":"xijing-zaji_ch-1","passageId":"xijing-zaji_ch-1_p-27","order":1,"canonicalText":"初修上林苑，群臣遠方，各獻名果異樹，亦有製為美名，以摽奇麗。","chunks":[]},{"id":"xijing-zaji_ch-1_p-27_s-2","chapterId":"xijing-zaji_ch-1","passageId":"xijing-zaji_ch-1_p-27","order":2,"canonicalText":"梨十：紫梨、青梨、芳梨、大谷梨、細葉梨、金村梨、夏梨、御兒梨、甘棠梨、香梨。","chunks":[]},{"id":"xijing-zaji_ch-1_p-27_s-3","chapterId":"xijing-zaji_ch-1","passageId":"xijing-zaji_ch-1_p-27","order":3,"canonicalText":"棗七：滑棗、酸棗、細腰棗、羊角棗、大白棗、桂棗、牛頭棗。","chunks":[]},{"id":"xijing-zaji_ch-1_p-28_s-1","chapterId":"xijing-zaji_ch-1","passageId":"xijing-zaji_ch-1_p-28","order":1,"canonicalText":"長安巧工丁緩者，為常滿燈，七龍五鳳，雜以芙蓉蓮藕之奇。","chunks":[]},{"id":"xijing-zaji_ch-1_p-28_s-2","chapterId":"xijing-zaji_ch-1","passageId":"xijing-zaji_ch-1_p-28","order":2,"canonicalText":"又作臥褥香鑪，一名被中香鑪。","chunks":[]},{"id":"xijing-zaji_ch-1_p-28_s-3","chapterId":"xijing-zaji_ch-1","passageId":"xijing-zaji_ch-1_p-28","order":3,"canonicalText":"本出房風，其法後絕，至緩始更為之。","chunks":[]},{"id":"xijing-zaji_ch-1_p-28_s-4","chapterId":"xijing-zaji_ch-1","passageId":"xijing-zaji_ch-1_p-28","order":4,"canonicalText":"設機關，運轉四周，而鑪體常平，可置之被褥中，故以為名。","chunks":[]},{"id":"xijing-zaji_ch-1_p-30_s-1","chapterId":"xijing-zaji_ch-1","passageId":"xijing-zaji_ch-1_p-30","order":1,"canonicalText":"趙後體輕腰弱，善行步進退，女弟昭儀不能及也。","chunks":[]},{"id":"xijing-zaji_ch-1_p-30_s-2","chapterId":"xijing-zaji_ch-1","passageId":"xijing-zaji_ch-1_p-30","order":2,"canonicalText":"但昭儀弱骨豐肌，尤工笑語。","chunks":[]},{"id":"xijing-zaji_ch-1_p-30_s-3","chapterId":"xijing-zaji_ch-1","passageId":"xijing-zaji_ch-1_p-30","order":3,"canonicalText":"二人並色如紅玉，為當時所絕。","chunks":[]},{"id":"xijing-zaji_ch-1_p-30_s-4","chapterId":"xijing-zaji_ch-1","passageId":"xijing-zaji_ch-1_p-30","order":4,"canonicalText":"成帝專寵，六宮無色。","chunks":[]},{"id":"xijing-zaji_ch-2_p-1_s-1","chapterId":"xijing-zaji_ch-2","passageId":"xijing-zaji_ch-2_p-1","order":1,"canonicalText":"元帝後宮既多，不得常見，乃使畫工圖形，案圖召幸之。","chunks":[]},{"id":"xijing-zaji_ch-2_p-1_s-2","chapterId":"xijing-zaji_ch-2","passageId":"xijing-zaji_ch-2_p-1","order":2,"canonicalText":"諸宮人皆賂畫工，多者十萬，少者亦不減五萬。","chunks":[]},{"id":"xijing-zaji_ch-2_p-1_s-3","chapterId":"xijing-zaji_ch-2","passageId":"xijing-zaji_ch-2_p-1","order":3,"canonicalText":"獨王嬙不肯，遂不得見。","chunks":[]},{"id":"xijing-zaji_ch-2_p-1_s-4","chapterId":"xijing-zaji_ch-2","passageId":"xijing-zaji_ch-2_p-1","order":4,"canonicalText":"後匈奴求美人，上案圖以嬙賜之。","chunks":[]},{"id":"xijing-zaji_ch-2_p-1_s-5","chapterId":"xijing-zaji_ch-2","passageId":"xijing-zaji_ch-2_p-1","order":5,"canonicalText":"及去，召見，貌為後宮第一，善應對，舉止閑雅。","chunks":[]},{"id":"xijing-zaji_ch-2_p-1_s-6","chapterId":"xijing-zaji_ch-2","passageId":"xijing-zaji_ch-2_p-1","order":6,"canonicalText":"帝悔之，而名籍已定。","chunks":[]},{"id":"xijing-zaji_ch-2_p-1_s-7","chapterId":"xijing-zaji_ch-2","passageId":"xijing-zaji_ch-2_p-1","order":7,"canonicalText":"帝乃窮案其事，畫工毛延壽、陳敞、劉白、龔寬皆棄巿。","chunks":[]},{"id":"xijing-zaji_ch-2_p-2_s-1","chapterId":"xijing-zaji_ch-2","passageId":"xijing-zaji_ch-2_p-2","order":1,"canonicalText":"武帝欲殺乳母，乳母告急於東方朔，朔曰：「帝忍而愎，旁人言之，益死之速耳。","chunks":[]},{"id":"xijing-zaji_ch-2_p-2_s-2","chapterId":"xijing-zaji_ch-2","passageId":"xijing-zaji_ch-2_p-2","order":2,"canonicalText":"汝臨去，但屢顧我，我當設奇救汝。","chunks":[]},{"id":"xijing-zaji_ch-2_p-2_s-3","chapterId":"xijing-zaji_ch-2","passageId":"xijing-zaji_ch-2_p-2","order":3,"canonicalText":"」及臨刑，乳母屢顧朔，朔叱之曰：「癡婦！","chunks":[]},{"id":"xijing-zaji_ch-2_p-2_s-4","chapterId":"xijing-zaji_ch-2","passageId":"xijing-zaji_ch-2_p-2","order":4,"canonicalText":"帝已長矣，豈復藉汝乳而活耶！","chunks":[]},{"id":"xijing-zaji_ch-2_p-2_s-5","chapterId":"xijing-zaji_ch-2","passageId":"xijing-zaji_ch-2_p-2","order":5,"canonicalText":"」帝悽然憫之，遂赦其罪。","chunks":[]},{"id":"xijing-zaji_ch-2_p-4_s-1","chapterId":"xijing-zaji_ch-2","passageId":"xijing-zaji_ch-2_p-4","order":1,"canonicalText":"公孫弘起家徒步，為丞相，故人高賀從之。","chunks":[]},{"id":"xijing-zaji_ch-2_p-4_s-2","chapterId":"xijing-zaji_ch-2","passageId":"xijing-zaji_ch-2_p-4","order":2,"canonicalText":"弘食以脫粟飯，覆以布被。","chunks":[]},{"id":"xijing-zaji_ch-2_p-4_s-3","chapterId":"xijing-zaji_ch-2","passageId":"xijing-zaji_ch-2_p-4","order":3,"canonicalText":"賀怨曰：「何用故人富貴為？","chunks":[]},{"id":"xijing-zaji_ch-2_p-4_s-4","chapterId":"xijing-zaji_ch-2","passageId":"xijing-zaji_ch-2_p-4","order":4,"canonicalText":"脫粟布被，與貧賤何異！","chunks":[]},{"id":"xijing-zaji_ch-2_p-4_s-5","chapterId":"xijing-zaji_ch-2","passageId":"xijing-zaji_ch-2_p-4","order":5,"canonicalText":"」弘自若，以俸祿皆散給故人貧乏者。","chunks":[]},{"id":"xijing-zaji_ch-2_p-5_s-1","chapterId":"xijing-zaji_ch-2","passageId":"xijing-zaji_ch-2_p-5","order":1,"canonicalText":"文帝自代還，有良馬九匹，皆天下之駿馬也。","chunks":[]},{"id":"xijing-zaji_ch-2_p-5_s-2","chapterId":"xijing-zaji_ch-2","passageId":"xijing-zaji_ch-2_p-5","order":2,"canonicalText":"一名浮雲，一名赤電，一名絕羣，一名逸驃，一名紫鷰騮，一名綠螭驄，一名龍子，一名嶙駒，一名絕塵，號為九逸。","chunks":[]},{"id":"xijing-zaji_ch-2_p-6_s-1","chapterId":"xijing-zaji_ch-2","passageId":"xijing-zaji_ch-2_p-6","order":1,"canonicalText":"武帝時，身毒國獻連環羈，皆以白玉作之，馬瑙石為勒，白光琉璃為鞍。","chunks":[]},{"id":"xijing-zaji_ch-2_p-6_s-2","chapterId":"xijing-zaji_ch-2","passageId":"xijing-zaji_ch-2_p-6","order":2,"canonicalText":"鞍在闇室中，常照十餘丈，如月光焉。","chunks":[]},{"id":"xijing-zaji_ch-2_p-7_s-1","chapterId":"xijing-zaji_ch-2","passageId":"xijing-zaji_ch-2_p-7","order":1,"canonicalText":"昭帝時，茂陵家人獻寶劍，上銘曰：直千金，壽萬歲。","chunks":[]},{"id":"xijing-zaji_ch-2_p-7_s-2","chapterId":"xijing-zaji_ch-2","passageId":"xijing-zaji_ch-2_p-7","order":2,"canonicalText":"上藏之於武庫，為國之鎮寶。","chunks":[]},{"id":"xijing-zaji_ch-2_p-8_s-1","chapterId":"xijing-zaji_ch-2","passageId":"xijing-zaji_ch-2_p-8","order":1,"canonicalText":"司馬相如初與卓文君還成都，居貧愁懣，以所著鷫鷞裘就巿人陽昌貰酒，與文君為懽。","chunks":[]},{"id":"xijing-zaji_ch-2_p-8_s-2","chapterId":"xijing-zaji_ch-2","passageId":"xijing-zaji_ch-2_p-8","order":2,"canonicalText":"既而文君抱頸而泣曰：「我非不能富，何至窮悴如此！","chunks":[]},{"id":"xijing-zaji_ch-2_p-8_s-3","chapterId":"xijing-zaji_ch-2","passageId":"xijing-zaji_ch-2_p-8","order":3,"canonicalText":"」相如乃與文君俱之臨邛，盡賣車騎，買一酒舍酤酒，文君當壚，相如滌器。","chunks":[]},{"id":"xijing-zaji_ch-2_p-9_s-1","chapterId":"xijing-zaji_ch-2","passageId":"xijing-zaji_ch-2_p-9","order":1,"canonicalText":"慶安世年十五，為成帝侍郎。","chunks":[]},{"id":"xijing-zaji_ch-2_p-9_s-2","chapterId":"xijing-zaji_ch-2","passageId":"xijing-zaji_ch-2_p-9","order":2,"canonicalText":"善鼓琴，能為《雙鳳離鸞》之曲。","chunks":[]},{"id":"xijing-zaji_ch-2_p-9_s-3","chapterId":"xijing-zaji_ch-2","passageId":"xijing-zaji_ch-2_p-9","order":3,"canonicalText":"趙後悅之，白上，得出入御內，絕見愛幸。","chunks":[]},{"id":"xijing-zaji_ch-2_p-10_s-1","chapterId":"xijing-zaji_ch-2","passageId":"xijing-zaji_ch-2_p-10","order":1,"canonicalText":"太上皇徙長安，居深宮，悽愴不樂。","chunks":[]},{"id":"xijing-zaji_ch-2_p-10_s-2","chapterId":"xijing-zaji_ch-2","passageId":"xijing-zaji_ch-2_p-10","order":2,"canonicalText":"高祖竊因左右問其故，以平生所好，皆屠販少年，酤酒賣餅，鬭鷄蹴踘，以此為歡，今皆無此，故不樂。","chunks":[]},{"id":"xijing-zaji_ch-2_p-10_s-3","chapterId":"xijing-zaji_ch-2","passageId":"xijing-zaji_ch-2_p-10","order":3,"canonicalText":"高祖乃作新豐，徙諸故人實之，太上皇乃悅。","chunks":[]},{"id":"xijing-zaji_ch-2_p-13_s-1","chapterId":"xijing-zaji_ch-2","passageId":"xijing-zaji_ch-2_p-13","order":1,"canonicalText":"司馬相如為《上林》、《子虛》賦，意思蕭散，不復與外事相關，控引天地，錯綜古今，忽然如睡，煥然如醒，賦成，遂大名於天下。","chunks":[]},{"id":"xijing-zaji_ch-2_p-14_s-1","chapterId":"xijing-zaji_ch-2","passageId":"xijing-zaji_ch-2_p-14","order":1,"canonicalText":"董仲舒夢蛟龍入懷，乃作《春秋繁露》詞。","chunks":[]},{"id":"xijing-zaji_ch-2_p-14_s-2","chapterId":"xijing-zaji_ch-2","passageId":"xijing-zaji_ch-2_p-14","order":2,"canonicalText":"其思深旨遠，天人感應之學，由此大備。","chunks":[]},{"id":"xijing-zaji_ch-2_p-16_s-1","chapterId":"xijing-zaji_ch-2","passageId":"xijing-zaji_ch-2_p-16","order":1,"canonicalText":"匡衡字稚圭，勤學而無燭。","chunks":[]},{"id":"xijing-zaji_ch-2_p-16_s-2","chapterId":"xijing-zaji_ch-2","passageId":"xijing-zaji_ch-2_p-16","order":2,"canonicalText":"鄰舍有燭而不逮，衡乃穿壁引其光，以書映光而讀之。","chunks":[]},{"id":"xijing-zaji_ch-2_p-16_s-3","chapterId":"xijing-zaji_ch-2","passageId":"xijing-zaji_ch-2_p-16","order":3,"canonicalText":"邑人大姓文不識，家富多書，衡乃與其傭作而不求償。","chunks":[]},{"id":"xijing-zaji_ch-2_p-16_s-4","chapterId":"xijing-zaji_ch-2","passageId":"xijing-zaji_ch-2_p-16","order":4,"canonicalText":"主人怪問衡，衡曰：「願得讀主人書。","chunks":[]},{"id":"xijing-zaji_ch-2_p-16_s-5","chapterId":"xijing-zaji_ch-2","passageId":"xijing-zaji_ch-2_p-16","order":5,"canonicalText":"」主人感嘆，資給以書，遂成大儒。","chunks":[]},{"id":"xijing-zaji_ch-2_p-17_s-1","chapterId":"xijing-zaji_ch-2","passageId":"xijing-zaji_ch-2_p-17","order":1,"canonicalText":"長安有儒生曰惠莊，聞朱雲折五鹿充宗之角，乃嘆息曰：「栗犢反能爾邪！","chunks":[]},{"id":"xijing-zaji_ch-2_p-17_s-2","chapterId":"xijing-zaji_ch-2","passageId":"xijing-zaji_ch-2_p-17","order":2,"canonicalText":"吾終恥溺死溝中。","chunks":[]},{"id":"xijing-zaji_ch-2_p-17_s-3","chapterId":"xijing-zaji_ch-2","passageId":"xijing-zaji_ch-2_p-17","order":3,"canonicalText":"」遂裹糧從師，精研《春秋》，亦為名儒。","chunks":[]},{"id":"xijing-zaji_ch-2_p-21_s-1","chapterId":"xijing-zaji_ch-2","passageId":"xijing-zaji_ch-2_p-21","order":1,"canonicalText":"元封二年，大寒，雪深五尺，野鳥獸皆死，牛馬皆踡蹜如蝟，三輔人民凍死者十有二三。","chunks":[]},{"id":"xijing-zaji_ch-2_p-21_s-2","chapterId":"xijing-zaji_ch-2","passageId":"xijing-zaji_ch-2_p-21","order":2,"canonicalText":"武帝下詔賑恤，發太倉粟以救之。","chunks":[]},{"id":"xijing-zaji_ch-2_p-22_s-1","chapterId":"xijing-zaji_ch-2","passageId":"xijing-zaji_ch-2_p-22","order":1,"canonicalText":"武帝為七寶牀，雜寶桉，廁寶屏風，列寶帳，設於桂宮，時人謂之四寶宮。","chunks":[]},{"id":"xijing-zaji_ch-2_p-22_s-2","chapterId":"xijing-zaji_ch-2","passageId":"xijing-zaji_ch-2_p-22","order":2,"canonicalText":"皆以夜光珠、珊瑚、琉璃為之。","chunks":[]},{"id":"xijing-zaji_ch-2_p-23_s-1","chapterId":"xijing-zaji_ch-2","passageId":"xijing-zaji_ch-2_p-23","order":1,"canonicalText":"瓠子河決，有蛟龍從九子自決中逆上入河，噴沫流波數十里。","chunks":[]},{"id":"xijing-zaji_ch-2_p-23_s-2","chapterId":"xijing-zaji_ch-2","passageId":"xijing-zaji_ch-2_p-23","order":2,"canonicalText":"武帝親臨決所，沈白馬玉璧以祭之，乃築宮其上，號曰宣房。","chunks":[]},{"id":"xijing-zaji_ch-2_p-24_s-1","chapterId":"xijing-zaji_ch-2","passageId":"xijing-zaji_ch-2_p-24","order":1,"canonicalText":"文帝初，多雨，積霖至百日而止。","chunks":[]},{"id":"xijing-zaji_ch-2_p-24_s-2","chapterId":"xijing-zaji_ch-2","passageId":"xijing-zaji_ch-2_p-24","order":2,"canonicalText":"京師米貴，斛至萬錢。","chunks":[]},{"id":"xijing-zaji_ch-2_p-24_s-3","chapterId":"xijing-zaji_ch-2","passageId":"xijing-zaji_ch-2_p-24","order":3,"canonicalText":"文帝減膳節用，開倉賑給，天下乃安。","chunks":[]},{"id":"xijing-zaji_ch-2_p-25_s-1","chapterId":"xijing-zaji_ch-2","passageId":"xijing-zaji_ch-2_p-25","order":1,"canonicalText":"王鳳以五月五日生，其父欲不舉，曰：「俗諺：『舉五日子，長及戶則自害，不則害其父母。","chunks":[]},{"id":"xijing-zaji_ch-2_p-25_s-2","chapterId":"xijing-zaji_ch-2","passageId":"xijing-zaji_ch-2_p-25","order":2,"canonicalText":"』」其叔父曰：「昔孟嘗君亦五月五日生，卒相齊。","chunks":[]},{"id":"xijing-zaji_ch-2_p-25_s-3","chapterId":"xijing-zaji_ch-2","passageId":"xijing-zaji_ch-2_p-25","order":3,"canonicalText":"何害之有！","chunks":[]},{"id":"xijing-zaji_ch-2_p-25_s-4","chapterId":"xijing-zaji_ch-2","passageId":"xijing-zaji_ch-2_p-25","order":4,"canonicalText":"」乃舉之，後果大貴，為大將軍。","chunks":[]},{"id":"xijing-zaji_ch-2_p-27_s-1","chapterId":"xijing-zaji_ch-2","passageId":"xijing-zaji_ch-2_p-27","order":1,"canonicalText":"高祖為泗水亭長，送徒驪山，將與故人訣去。","chunks":[]},{"id":"xijing-zaji_ch-2_p-27_s-2","chapterId":"xijing-zaji_ch-2","passageId":"xijing-zaji_ch-2_p-27","order":2,"canonicalText":"徒卒贈高祖酒二壼，鹿肚、牛肝各一。","chunks":[]},{"id":"xijing-zaji_ch-2_p-27_s-3","chapterId":"xijing-zaji_ch-2","passageId":"xijing-zaji_ch-2_p-27","order":3,"canonicalText":"高祖與樂從者飲酒於豐西澤中，夜斬白蛇，遂起義兵。","chunks":[]},{"id":"xijing-zaji_ch-2_p-28_s-1","chapterId":"xijing-zaji_ch-2","passageId":"xijing-zaji_ch-2_p-28","order":1,"canonicalText":"梁孝王好營宮室苑囿之樂，作曜華之宮，築兔園。","chunks":[]},{"id":"xijing-zaji_ch-2_p-28_s-2","chapterId":"xijing-zaji_ch-2","passageId":"xijing-zaji_ch-2_p-28","order":2,"canonicalText":"園中有百靈山，山有膚寸石、落猿巖、棲龍岫；","chunks":[]},{"id":"xijing-zaji_ch-2_p-28_s-3","chapterId":"xijing-zaji_ch-2","passageId":"xijing-zaji_ch-2_p-28","order":3,"canonicalText":"又有雁池，池中有鶴洲、鳧渚。","chunks":[]},{"id":"xijing-zaji_ch-2_p-28_s-4","chapterId":"xijing-zaji_ch-2","passageId":"xijing-zaji_ch-2_p-28","order":4,"canonicalText":"天下名士鄒陽、枚乘、司馬相如皆遊其間，極一時之盛。","chunks":[]},{"id":"xijing-zaji_ch-2_p-29_s-1","chapterId":"xijing-zaji_ch-2","passageId":"xijing-zaji_ch-2_p-29","order":1,"canonicalText":"魯恭王好鬭雞鴨及鵝鴈，養孔雀、鵁鶄，俸穀一年費二千石。","chunks":[]},{"id":"xijing-zaji_ch-2_p-29_s-2","chapterId":"xijing-zaji_ch-2","passageId":"xijing-zaji_ch-2_p-29","order":2,"canonicalText":"又壞孔子舊宅以廣其宮，聞金石絲竹之聲，乃不敢壞。","chunks":[]},{"id":"xijing-zaji_ch-2_p-30_s-1","chapterId":"xijing-zaji_ch-2","passageId":"xijing-zaji_ch-2_p-30","order":1,"canonicalText":"會稽歲時獻竹簟供御，世號為流黃簟。","chunks":[]},{"id":"xijing-zaji_ch-2_p-30_s-2","chapterId":"xijing-zaji_ch-2","passageId":"xijing-zaji_ch-2_p-30","order":2,"canonicalText":"簟色如黃金，而滑澤如冰，夏月寢之，清涼徹骨。","chunks":[]}]}') as WorkBundle
